/* ============================= SUPABASE ============================= */
// Lê de variáveis de ambiente (VITE_SUPABASE_URL / VITE_SUPABASE_ANON_KEY) quando disponíveis
// (ex: configuradas no painel da Netlify); caso contrário, usa os valores do projeto abaixo.
// A chave "publishable/anon" é feita pra ser pública — a proteção real fica nas regras (RLS) do banco.
const ENV = (typeof import.meta !== "undefined" && import.meta.env) || {};
const SUPABASE_URL = ENV.VITE_SUPABASE_URL || "https://ykdfbqfafogwfohncrrp.supabase.co";
const SUPABASE_ANON_KEY = ENV.VITE_SUPABASE_ANON_KEY || "sb_publishable_8NOkOhyqZhNx0i33X1zhkg_7nMaqQ-v";
const SUPABASE_BUCKET = "imagens";
const SUPABASE_TABLE = "imagens";

const supabase = createClient(SUPABASE_URL, SUPABASE_ANON_KEY);

// Envia um arquivo (foto ou vídeo) pro Supabase Storage e registra os metadados na tabela "imagens".
// Retorna a URL pública, já pronta pra usar em <img>/<video> ou salvar no produto/banner/categoria.
async function uploadToSupabase(file, folder) {
  const ext = (file.name.split(".").pop() || "bin").toLowerCase();
  const path = `${folder}/${Date.now()}-${Math.random().toString(36).slice(2)}.${ext}`;

  const { error: uploadError } = await supabase.storage
    .from(SUPABASE_BUCKET)
    .upload(path, file, { cacheControl: "3600", upsert: false });
  if (uploadError) throw uploadError;

  const { data } = supabase.storage.from(SUPABASE_BUCKET).getPublicUrl(path);
  const publicUrl = data.publicUrl;

  const { error: dbError } = await supabase.from(SUPABASE_TABLE).insert({
    name: file.name,
    url: publicUrl,
  });
  if (dbError) console.error(`Upload feito, mas não foi possível registrar em "${SUPABASE_TABLE}":`, dbError.message);

  return publicUrl;
}

// Remove uma mídia do Storage e do registro na tabela "imagens", a partir da URL pública salva.
async function deleteFromSupabaseByUrl(url) {
  if (!url) return;
  const marker = `/${SUPABASE_BUCKET}/`;
  const idx = url.indexOf(marker);
  if (idx === -1) return;
  const path = url.slice(idx + marker.length);
  try {
    await supabase.storage.from(SUPABASE_BUCKET).remove([path]);
    await supabase.from(SUPABASE_TABLE).delete().eq("url", url);
  } catch (err) {
    console.error("Não foi possível excluir a mídia do Supabase:", err.message);
  }
}

