function Toast({ toast, onClose }) {
  useEffect(() => {
    if (!toast) return;
    const t = setTimeout(onClose, 3200);
    return () => clearTimeout(t);
  }, [toast]);

  if (!toast) return null;
  const Icon = toast.type === "success" ? Check : X;
  return (
    <div className={`toast toast-${toast.type}`}>
      <Icon className="w-4 h-4" />
      <span>{toast.message}</span>
    </div>
  );
}

function FileField({ onFiles, accept, multiple = false, className = "", children }) {
  return (
    <span className={`file-field ${className}`}>
      {children}
      <input
        type="file"
        accept={accept}
        multiple={multiple}
        onChange={(e) => {
          const files = Array.from(e.target.files || []);
          if (files.length) onFiles(files);
          e.target.value = "";
        }}
      />
    </span>
  );
}

function Reveal({ children, className = "", delay = 0 }) {
  const ref = useRef(null);
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (typeof IntersectionObserver === "undefined") {
      setVisible(true);
      return;
    }
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setVisible(true);
            observer.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.12, rootMargin: "0px 0px -40px 0px" }
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  return (
    <div ref={ref} className={`reveal ${visible ? "reveal-visible" : ""} ${className}`} style={{ transitionDelay: `${delay}ms` }}>
      {children}
    </div>
  );
}

function StarRating({ rating, reviews, size = "sm" }) {
  const full = Math.round(rating);
  return (
    <div className="flex items-center gap-1.5">
      <div className="flex items-center gap-0.5">
        {[1, 2, 3, 4, 5].map((i) => (
          <Star key={i} className={size === "sm" ? "w-3.5 h-3.5" : "w-4 h-4"}
            style={{ fill: i <= full ? "#D6A32C" : "none", color: i <= full ? "#D6A32C" : "#C9C5B6" }} />
        ))}
      </div>
      {reviews != null && <span className="txt-muted" style={{ fontSize: "0.75rem" }}>({reviews})</span>}
    </div>
  );
}

function ProductVisual({ product, className = "" }) {
  const cat = CATEGORIES.find((c) => c.id === product.category);
  const Icon = cat?.icon || Package;
  const outOfStock = product.stock <= 0;
  const hasPhoto = !!product.image;
  return (
    <div
      className={`prod-visual ${hasPhoto ? "prod-visual-photo" : ""} ${outOfStock ? "prod-visual-out" : ""} ${className}`}
      style={hasPhoto ? { backgroundImage: `url(${product.image})` } : undefined}
    >
      {!hasPhoto && (
        <>
          <div className="prod-floor-shadow" />
          <div className={`prod-container-lid ${cat?.tint || "t-forest"}`} />
          <div className="prod-container-body">
            <Icon className="prod-visual-icon" strokeWidth={1.2} />
          </div>
        </>
      )}
      {hasPhoto && <div className="prod-visual-gradient" />}
      <div className="prod-visual-scrim" />
      {outOfStock ? (
        <span className="badge-pill badge-esgotado">Esgotado</span>
      ) : product.badge ? (
        <span className={`badge-pill badge-${product.badge}`}>
          {product.badge === "mais-vendido" ? "Mais vendido" : product.badge === "oferta" ? "Oferta" : "Novo"}
        </span>
      ) : null}
    </div>
  );
}

function ProductCard({ product, onView, onAddToCart, compact }) {
  const discount = product.oldPrice ? Math.round((1 - product.price / product.oldPrice) * 100) : null;
  const outOfStock = product.stock <= 0;
  const handleAdd = (e) => { e.stopPropagation(); onAddToCart(product, 1); };
  return (
    <div className={`product-card ${compact ? "product-card-compact" : ""} ${outOfStock ? "product-card-out" : ""}`}
      onClick={() => onView(product.id)} role="button" tabIndex={0}>
      <ProductVisual product={product} />
      <div className="product-card-overlay">
        {product.oldPrice && discount && <span className="price-discount price-discount-overlay">-{discount}%</span>}
        <h3 className="prod-title-overlay">{product.name}</h3>
        <StarRating rating={product.rating} reviews={product.reviews} />
        <div className="price-row">
          {product.oldPrice && <span className="price-old price-old-overlay">{formatPrice(product.oldPrice)}</span>}
          <span className="price-now price-now-overlay">{formatPrice(product.price)}</span>
        </div>
        {outOfStock ? (
          <button className="btn btn-sm btn-disabled btn-card-cta" disabled onClick={(e) => e.stopPropagation()}>Esgotado</button>
        ) : (
          <button className="btn btn-primary btn-sm btn-card-cta" onClick={handleAdd}>
            <ShoppingCart className="w-4 h-4" /> Adicionar ao carrinho
          </button>
        )}
      </div>
    </div>
  );
}


