/* ============================= PÁGINA: BUSCA / CATÁLOGO ============================= */

function BuscaPage({ products, initialQuery, initialCategory, goTo, addToCart, viewProduct }) {
  const [query, setQuery] = useState(initialQuery || "");
  const [category, setCategory] = useState(initialCategory || "todas");
  const [sort, setSort] = useState("relevancia");
  const [maxPrice, setMaxPrice] = useState(200);
  const [filtersOpen, setFiltersOpen] = useState(false);

  const filtered = useMemo(() => {
    let list = products.filter((p) => p.name.toLowerCase().includes(query.toLowerCase()));
    if (category !== "todas") list = list.filter((p) => p.category === category);
    list = list.filter((p) => p.price <= maxPrice);
    if (sort === "menor-preco") list = [...list].sort((a, b) => a.price - b.price);
    else if (sort === "maior-preco") list = [...list].sort((a, b) => b.price - a.price);
    else if (sort === "avaliacao") list = [...list].sort((a, b) => b.rating - a.rating);
    else if (sort === "novidades") list = [...list].sort((a, b) => (b.badge === "novo") - (a.badge === "novo"));
    else if (sort === "mais-vendidos") list = [...list].sort((a, b) => (b.badge === "mais-vendido") - (a.badge === "mais-vendido"));
    return list;
  }, [products, query, category, sort, maxPrice]);

  return (
    <div className="page-shell">
      <h1 className="page-title">Produtos</h1>
      <div className="busca-layout">
        <aside className={`filters-panel ${filtersOpen ? "filters-open" : ""}`}>
          <div className="filters-head only-mobile">
            <h3>Filtros</h3>
            <button className="icon-btn" onClick={() => setFiltersOpen(false)}><X className="w-5 h-5" /></button>
          </div>
          <div className="filter-block">
            <label>Buscar</label>
            <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="ex: pote" />
          </div>
          <div className="filter-block">
            <label>Categoria</label>
            <select value={category} onChange={(e) => setCategory(e.target.value)}>
              <option value="todas">Todas as categorias</option>
              {CATEGORIES.filter((c) => c.id !== "ofertas").map((c) => (
                <option key={c.id} value={c.id}>{c.name}</option>
              ))}
            </select>
          </div>
          <div className="filter-block">
            <label>Preço até {formatPrice(maxPrice)}</label>
            <input type="range" min="20" max="200" value={maxPrice} onChange={(e) => setMaxPrice(Number(e.target.value))} />
          </div>
          <div className="filter-block">
            <label>Ordenar por</label>
            <select value={sort} onChange={(e) => setSort(e.target.value)}>
              <option value="relevancia">Relevância</option>
              <option value="mais-vendidos">Mais vendidos</option>
              <option value="novidades">Novidades</option>
              <option value="menor-preco">Menor preço</option>
              <option value="maior-preco">Maior preço</option>
              <option value="avaliacao">Melhor avaliação</option>
            </select>
          </div>
        </aside>

        <div className="busca-results">
          <div className="busca-toolbar">
            <span className="txt-muted">{filtered.length} produto{filtered.length !== 1 ? "s" : ""} encontrado{filtered.length !== 1 ? "s" : ""}</span>
            <button className="btn btn-outline btn-sm only-mobile" onClick={() => setFiltersOpen(true)}><Filter className="w-4 h-4" /> Filtros</button>
          </div>
          {filtered.length === 0 ? (
            <div className="empty-state">Nenhum produto encontrado. Tente ajustar os filtros.</div>
          ) : (
            <div className="product-grid">
              {filtered.map((p) => (
                <ProductCard key={p.id} product={p} onView={viewProduct} onAddToCart={addToCart} />
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

