function ProductPage({ product, allProducts, goTo, addToCart, viewProduct }) {
  const [qty, setQty] = useState(1);
  const [color, setColor] = useState(Object.keys(SWATCHES)[0]);
  if (!product) return <div className="page-shell"><p>Produto não encontrado.</p></div>;

  const discount = product.oldPrice ? Math.round((1 - product.price / product.oldPrice) * 100) : null;
  const related = allProducts.filter((p) => p.category === product.category && p.id !== product.id).slice(0, 4);
  const waMsg = `Olá! Tenho interesse no produto ${product.name}. Gostaria de saber mais informações.`;

  return (
    <div className="page-shell">
      <button className="link-more" onClick={() => goTo("busca")} style={{ marginBottom: "1rem" }}>
        <ChevronLeft className="w-4 h-4" /> Voltar aos produtos
      </button>
      <div className="product-detail">
        <div className="product-gallery">
          <ProductVisual product={product} className="prod-visual-big" />
          <div className="gallery-thumbs">
            {Object.entries(SWATCHES).map(([name, hex]) => (
              <button key={name} className={`thumb ${color === name ? "thumb-active" : ""}`} style={{ background: hex }} onClick={() => setColor(name)} aria-label={name} />
            ))}
          </div>
        </div>
        <div className="product-info">
          <span className="badge-pill" style={{ position: "static", display: "inline-flex" }}>{CATEGORIES.find((c) => c.id === product.category)?.name}</span>
          <h1>{product.name}</h1>
          <StarRating rating={product.rating} reviews={product.reviews} size="md" />
          <div className="price-row" style={{ marginTop: "0.75rem" }}>
            {product.oldPrice && <span className="price-old">{formatPrice(product.oldPrice)}</span>}
            <span className="price-now price-now-lg">{formatPrice(product.price)}</span>
            {discount && <span className="price-discount">-{discount}%</span>}
          </div>
          <div className="txt-muted">ou em até 3x de {formatPrice(product.price / 3)} sem juros</div>
          <p className="product-desc">{product.desc}</p>

          <div className="filter-block">
            <label>Cor: <strong>{color}</strong></label>
            <div className="gallery-thumbs">
              {Object.entries(SWATCHES).map(([name, hex]) => (
                <button key={name} className={`thumb ${color === name ? "thumb-active" : ""}`} style={{ background: hex }} onClick={() => setColor(name)} aria-label={name} />
              ))}
            </div>
          </div>

          <div className="qty-row">
            <label>Quantidade</label>
            <div className="stepper">
              <button onClick={() => setQty((q) => Math.max(1, q - 1))} disabled={product.stock <= 0}><Minus className="w-4 h-4" /></button>
              <span>{qty}</span>
              <button onClick={() => setQty((q) => q + 1)} disabled={product.stock <= 0}><Plus className="w-4 h-4" /></button>
            </div>
            <span className={product.stock <= 0 ? "coupon-err" : "txt-muted"} style={{ fontSize: "0.78rem" }}>
              {product.stock <= 0 ? "Produto esgotado no momento" : `${product.stock} em estoque`}
            </span>
          </div>

          {product.stock <= 0 ? (
            <>
              <div className="product-cta-row">
                <button className="btn btn-disabled" disabled style={{ flex: 1 }}>Produto esgotado</button>
              </div>
              <a className="btn btn-whatsapp" href={waLink(`Olá! Gostaria de saber quando o produto ${product.name} volta ao estoque.`)} target="_blank" rel="noopener noreferrer">
                <MessageCircle className="w-4 h-4" /> Avise-me quando chegar
              </a>
            </>
          ) : (
            <>
              <div className="product-cta-row">
                <button className="btn btn-outline" onClick={() => addToCart(product, qty, color)}><ShoppingCart className="w-4 h-4" /> Adicionar ao carrinho</button>
                <button className="btn btn-primary" onClick={() => { addToCart(product, qty, color); goTo("carrinho"); }}>Comprar agora</button>
              </div>
              <a className="btn btn-whatsapp" href={waLink(waMsg)} target="_blank" rel="noopener noreferrer">
                <MessageCircle className="w-4 h-4" /> Comprar pelo WhatsApp
              </a>
            </>
          )}

          <div className="spec-table">
            <div><span>Capacidade</span><span>{product.capacity}</span></div>
            <div><span>Material</span><span>{product.material}</span></div>
            <div><span>Categoria</span><span>{CATEGORIES.find((c) => c.id === product.category)?.name}</span></div>
          </div>

          <ul className="feature-list">
            {product.features.map((f, i) => <li key={i}><Check className="w-4 h-4" /> {f}</li>)}
          </ul>

          <div className="trust-row">
            <span><Truck className="w-4 h-4" /> Envio para todo o Brasil</span>
            <span><ShieldCheck className="w-4 h-4" /> Compra 100% segura</span>
          </div>
        </div>
      </div>

      {related.length > 0 && (
        <Reveal>
          <section className="section">
            <h2 className="section-title">Você também pode gostar</h2>
            <div className="product-grid">
              {related.map((p) => <ProductCard key={p.id} product={p} onView={viewProduct} onAddToCart={addToCart} />)}
            </div>
          </section>
        </Reveal>
      )}
    </div>
  );
}

/* ============================= PÁGINA: CARRINHO ============================= */

function CartPage({ cart, products, updateQty, removeItem, goTo, clearCart, coupons = [], addOrder }) {
  const [coupon, setCoupon] = useState("");
  const [couponMsg, setCouponMsg] = useState(null);
  const [discountPct, setDiscountPct] = useState(0);
  const [appliedCode, setAppliedCode] = useState(null);
  const [obs, setObs] = useState("");
  const [customerName, setCustomerName] = useState("");
  const [nameError, setNameError] = useState("");
  const [payment, setPayment] = useState(null);
  const [paymentError, setPaymentError] = useState("");

  const PAYMENT_OPTIONS = [
    { id: "pix", label: "Pix" },
    { id: "dinheiro", label: "Dinheiro" },
    { id: "cartao", label: "Cartão" },
  ];

  const items = cart.map((ci) => ({ ...ci, product: products.find((p) => p.id === ci.productId) })).filter((i) => i.product);
  const subtotal = items.reduce((s, i) => s + i.product.price * i.qty, 0);
  const discountVal = subtotal * discountPct;
  const total = subtotal - discountVal;

  const isExpired = (validade) => {
    if (!validade) return false;
    const d = new Date(validade + "T23:59:59");
    return !isNaN(d.getTime()) && d < new Date();
  };

  const applyCoupon = () => {
    const code = coupon.trim().toUpperCase();
    const found = coupons.find((c) => c.code.toUpperCase() === code && c.active !== false);
    if (!found) {
      setDiscountPct(0);
      setAppliedCode(null);
      setCouponMsg({ ok: false, text: "Cupom inválido." });
      return;
    }
    if (isExpired(found.validade)) {
      setDiscountPct(0);
      setAppliedCode(null);
      setCouponMsg({ ok: false, text: "Esse cupom já expirou." });
      return;
    }
    setDiscountPct(found.discount / 100);
    setAppliedCode(found.code);
    setCouponMsg({ ok: true, text: `Cupom aplicado: ${found.discount}% de desconto.` });
  };

  const productsBlock = items
    .map((i) => `• ${i.product.name}\nQtd: ${i.qty}\nValor: ${formatPrice(i.product.price)}`)
    .join("\n\n");

  const waFinishMsg =
    `Olá! Gostaria de fazer o seguinte pedido:\n\n` +
    `🛍️ Produtos:\n\n` +
    `${productsBlock}\n\n` +
    `-------------------------\n` +
    (discountVal > 0 ? `Desconto: -${formatPrice(discountVal)}\n` : "") +
    `Total: ${formatPrice(total)}\n\n` +
    `Nome: ${customerName.trim()}\n` +
    `Forma de pagamento: ${PAYMENT_OPTIONS.find((p) => p.id === payment)?.label || ""}\n` +
    `Endereço:\n` +
    (obs.trim() ? `Observações: ${obs.trim()}\n\n` : "\n") +
    `Aguardo seu atendimento. Obrigado!`;

  const sendOrder = () => {
    const nameOk = customerName.trim().split(/\s+/).filter(Boolean).length >= 2;
    if (!nameOk) {
      setNameError("Escreva seu nome completo (nome e sobrenome).");
      return;
    }
    if (!payment) {
      setPaymentError("Escolha uma forma de pagamento.");
      return;
    }
    setNameError("");
    setPaymentError("");
    if (addOrder) {
      addOrder({
        id: "#" + Date.now().toString().slice(-6),
        cliente: customerName.trim(),
        payment: PAYMENT_OPTIONS.find((p) => p.id === payment)?.label,
        items: items.map((i) => ({ name: i.product.name, qty: i.qty, price: i.product.price })),
        subtotal, discount: discountVal, total,
        coupon: appliedCode, obs: obs.trim(),
        status: "Novo",
        date: new Date().toISOString(),
      });
    }
    window.open(waLink(waFinishMsg), "_blank", "noopener,noreferrer");
    clearCart();
  };

  if (items.length === 0) {
    return (
      <div className="page-shell">
        <h1 className="page-title">Seu carrinho</h1>
        <div className="empty-state">
          <ShoppingCart className="w-8 h-8" style={{ marginBottom: "0.5rem" }} />
          <p>Seu carrinho está vazio.</p>
          <button className="btn btn-primary" onClick={() => goTo("busca")} style={{ marginTop: "1rem" }}>Continuar comprando</button>
        </div>
      </div>
    );
  }

  return (
    <div className="page-shell">
      <h1 className="page-title">Seu carrinho</h1>
      <div className="cart-layout">
        <div className="cart-items">
          {items.map((i) => (
            <div key={i.productId + i.color} className="cart-item" style={{ display: "flex", flexDirection: "column", gap: "0.75rem", padding: "1rem", border: "1px solid #e5e7eb", borderRadius: "0.75rem", marginBottom: "0.75rem" }}>
              <div style={{ display: "flex", gap: "0.75rem", alignItems: "flex-start" }}>
                <ProductVisual product={i.product} className="cart-item-visual" />
                <div style={{ flex: 1 }}>
                  <div style={{ fontWeight: 600, marginBottom: "0.2rem" }}>{i.product.name}</div>
                  <div style={{ fontSize: "0.78rem", color: "#6b7280", marginBottom: "0.25rem" }}>Cor: {i.color}</div>
                  <div className="price-now">{formatPrice(i.product.price)}</div>
                </div>
                <button className="icon-btn" onClick={() => removeItem(i.productId, i.color)} aria-label="Remover"><Trash2 className="w-4 h-4" /></button>
              </div>
              <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
                <div style={{ display: "flex", alignItems: "center", gap: "0.75rem", border: "1px solid #e5e7eb", borderRadius: "2rem", padding: "0.3rem 0.75rem" }}>
                  <button style={{ background: "none", border: "none", cursor: "pointer", display: "flex", alignItems: "center", padding: "0.2rem" }} onClick={() => updateQty(i.productId, i.color, Math.max(1, i.qty - 1))}><Minus className="w-4 h-4" /></button>
                  <span style={{ minWidth: "1.5rem", textAlign: "center", fontWeight: 600 }}>{i.qty}</span>
                  <button style={{ background: "none", border: "none", cursor: "pointer", display: "flex", alignItems: "center", padding: "0.2rem" }} onClick={() => updateQty(i.productId, i.color, i.qty + 1)}><Plus className="w-4 h-4" /></button>
                </div>
                <span style={{ fontWeight: 700, fontSize: "1rem" }}>{formatPrice(i.product.price * i.qty)}</span>
              </div>
            </div>
          ))}
          <button className="link-more" onClick={() => goTo("busca")}><ChevronLeft className="w-4 h-4" /> Continuar comprando</button>
        </div>

        <div className="cart-summary">
          <h3>Resumo do pedido</h3>
          <div className="coupon-row">
            <input placeholder="Possui cupom de desconto?" value={coupon}
              onChange={(e) => setCoupon(e.target.value)}
              onKeyDown={(e) => { if (e.key === "Enter") applyCoupon(); }} />
            <button className="btn btn-outline btn-sm" type="button" onClick={applyCoupon}>Aplicar</button>
          </div>
          {couponMsg && <div className={couponMsg.ok ? "coupon-ok" : "coupon-err"}>{couponMsg.text}</div>}
          <div className="summary-row"><span>Subtotal</span><span>{formatPrice(subtotal)}</span></div>
          {discountVal > 0 && <div className="summary-row summary-discount"><span>Desconto</span><span>-{formatPrice(discountVal)}</span></div>}
          <div className="summary-row summary-total"><span>Total</span><span>{formatPrice(total)}</span></div>

          <div className="filter-block" style={{ marginTop: "0.75rem" }}>
            <label>Nome completo</label>
            <input placeholder="Digite seu nome completo" value={customerName}
              onChange={(e) => { setCustomerName(e.target.value); setNameError(""); }} />
            {nameError && <span className="coupon-err">{nameError}</span>}
          </div>

          <div className="filter-block" style={{ marginTop: "0.75rem" }}>
            <label>Forma de pagamento</label>
            <div className="payment-radio-group">
              {PAYMENT_OPTIONS.map((p) => (
                <label key={p.id} className={`payment-radio-option ${payment === p.id ? "payment-radio-active" : ""}`}>
                  <input
                    type="radio"
                    name="payment-method"
                    checked={payment === p.id}
                    onChange={() => { setPayment(p.id); setPaymentError(""); }}
                  />
                  <span className="payment-radio-dot" />
                  {p.label}
                </label>
              ))}
            </div>
            {paymentError && <span className="coupon-err">{paymentError}</span>}
          </div>

          <div className="filter-block" style={{ marginTop: "0.5rem" }}>
            <label>Observações (opcional)</label>
            <textarea rows={3} placeholder="Ex: quero retirar na loja, entregar amanhã..." value={obs} onChange={(e) => setObs(e.target.value)} />
          </div>

          <button type="button" className="btn btn-primary" style={{ width: "100%", justifyContent: "center", marginTop: "0.5rem" }} onClick={sendOrder}>
            <MessageCircle className="w-4 h-4" /> Enviar pedido pelo WhatsApp
          </button>
          <p className="txt-muted" style={{ fontSize: "0.78rem", marginTop: "0.6rem", textAlign: "center" }}>Seu pedido será aberto no WhatsApp, já preenchido, para combinar pagamento e entrega.</p>
        </div>
      </div>
    </div>
  );
}

