/* ============================= PÁGINA: LOGIN ADMIN ============================= */

function AdminLogin({ onSuccess, goTo }) {
  const [email, setEmail] = useState("");
  const [pwd, setPwd] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const tryLogin = async () => {
    if (!email.trim() || !pwd.trim()) { setError("Preencha e-mail e senha."); return; }
    setLoading(true);
    setError("");
    const { error: authError } = await supabase.auth.signInWithPassword({ email: email.trim(), password: pwd });
    setLoading(false);
    if (authError) { setError("E-mail ou senha incorretos."); return; }
    onSuccess();
  };

  return (
    <div className="page-shell admin-login-shell">
      <div className="admin-login-card">
        <div className="admin-login-icon"><Lock className="w-6 h-6" /></div>
        <h1 className="page-title" style={{ marginBottom: "0.35rem" }}>Área restrita</h1>
        <p className="txt-muted" style={{ marginBottom: "1.25rem" }}>Digite suas credenciais de administrador.</p>
        <div className="admin-login-form">
          <input
            type="email"
            placeholder="E-mail"
            value={email}
            onChange={(e) => { setEmail(e.target.value); setError(""); }}
            onKeyDown={(e) => { if (e.key === "Enter") tryLogin(); }}
            autoFocus
          />
          <input
            type="password"
            placeholder="Senha"
            value={pwd}
            onChange={(e) => { setPwd(e.target.value); setError(""); }}
            onKeyDown={(e) => { if (e.key === "Enter") tryLogin(); }}
            style={{ marginTop: "0.5rem" }}
          />
          {error && <span className="coupon-err">{error}</span>}
          <button type="button" className="btn btn-primary" style={{ width: "100%" }} onClick={tryLogin} disabled={loading}>
            {loading ? "Entrando…" : "Entrar"}
          </button>
        </div>
        <button className="link-more" onClick={() => goTo("home")} style={{ marginTop: "1rem" }}>Voltar à loja</button>
      </div>
    </div>
  );
}

/* ============================= PÁGINA: ADMIN (DEMO) ============================= */

function AdminPage({ products, setProducts, categoryImages, setCategoryImages, heroImages, setHeroImages, howToImages, setHowToImages, coupons, setCoupons, orders, setOrders, onSaveAll, isSaving, onLogout, galeriaImagens, setGaleriaImagens, hiddenCategories, setHiddenCategories }) {
  const [tab, setTab] = useState("produtos");
  const [editing, setEditing] = useState(null);
  const emptyForm = { name: "", category: "potes", price: "", stock: "", images: [], video: null };
  const [form, setForm] = useState(emptyForm);
  const [imgError, setImgError] = useState("");
  const [videoError, setVideoError] = useState("");
  const [formError, setFormError] = useState("");

  const startNew = () => { setEditing("new"); setForm(emptyForm); setImgError(""); setVideoError(""); setFormError(""); };
  const startEdit = (p) => { setEditing(p.id); setForm({ name: p.name, category: p.category, price: p.price, stock: p.stock, images: p.images && p.images.length ? p.images : (p.image ? [p.image] : []), video: p.video || null }); setImgError(""); setVideoError(""); setFormError(""); };
  const cancel = () => { setEditing(null); setForm(emptyForm); setImgError(""); setVideoError(""); setFormError(""); };

  const [uploadingImages, setUploadingImages] = useState(false);
  const handleProductImages = async (files) => {
    if (form.images.length + files.length > 6) {
      setImgError("Máximo de 6 fotos por produto.");
      return;
    }
    const tooBig = files.find((f) => f.size > 8 * 1024 * 1024);
    if (tooBig) {
      setImgError("Cada foto deve ter até 8MB.");
      return;
    }
    setImgError("");
    setUploadingImages(true);
    try {
      const urls = await Promise.all(files.map((f) => uploadToSupabase(f, "produtos")));
      setForm((f) => ({ ...f, images: [...f.images, ...urls] }));
    } catch (err) {
      setImgError("Não foi possível enviar a foto: " + err.message);
    } finally {
      setUploadingImages(false);
    }
  };

  const removeImage = (idx) => {
    const url = form.images[idx];
    setForm((f) => ({ ...f, images: f.images.filter((_, i) => i !== idx) }));
    deleteFromSupabaseByUrl(url);
  };

  const [uploadingVideo, setUploadingVideo] = useState(false);
  const handleProductVideo = async (files) => {
    const file = files[0];
    if (!file) return;
    if (file.size > 100 * 1024 * 1024) {
      setVideoError("Vídeo muito grande. Escolha um arquivo de até 100MB.");
      return;
    }
    setVideoError("");
    setUploadingVideo(true);
    try {
      const url = await uploadToSupabase(file, "produtos-video");
      setForm((f) => ({ ...f, video: url }));
    } catch (err) {
      setVideoError("Não foi possível enviar o vídeo: " + err.message);
    } finally {
      setUploadingVideo(false);
    }
  };

  const save = () => {
    if (!form.name.trim() || !form.price || form.stock === "") {
      setFormError("Preencha nome, preço e estoque para salvar.");
      return;
    }
    setFormError("");
    if (editing === "new") {
      const newId = Math.max(0, ...products.map((p) => p.id)) + 1;
      setProducts([...products, {
        id: newId, name: form.name, category: form.category, price: Number(form.price), oldPrice: null,
        rating: 5, reviews: 0, badge: "novo", stock: Number(form.stock),
        images: form.images, image: form.images[0] || null, video: form.video,
        desc: "Novo produto cadastrado pelo painel administrativo.", features: [], capacity: "-", material: "-",
      }]);
    } else {
      setProducts(products.map((p) => p.id === editing
        ? { ...p, name: form.name, category: form.category, price: Number(form.price), stock: Number(form.stock), images: form.images, image: form.images[0] || null, video: form.video }
        : p));
    }
    cancel();
  };

  const remove = (id) => {
    const p = products.find((x) => x.id === id);
    setProducts(products.filter((x) => x.id !== id));
    if (p) {
      (p.images || []).forEach((url) => deleteFromSupabaseByUrl(url));
      if (p.video) deleteFromSupabaseByUrl(p.video);
    }
  };

  const toggleEsgotado = (p) => {
    if (p.stock > 0) {
      setProducts(products.map((x) => x.id === p.id ? { ...x, stock: 0, lastStock: p.stock } : x));
    } else {
      setProducts(products.map((x) => x.id === p.id ? { ...x, stock: x.lastStock || 10 } : x));
    }
  };

  const [catImgError, setCatImgError] = useState("");
  const [uploadingCatId, setUploadingCatId] = useState(null);
  const handleCategoryImage = (categoryId) => async (files) => {
    const file = files[0];
    if (!file) return;
    if (file.size > 8 * 1024 * 1024) {
      setCatImgError("Imagem muito grande. Escolha um arquivo de até 8MB.");
      return;
    }
    setCatImgError("");
    setUploadingCatId(categoryId);
    try {
      const url = await uploadToSupabase(file, "categorias");
      await supabase.from("app_category_images").delete().eq("category_id", categoryId);
      const { error: saveErr } = await supabase.from("app_category_images").insert({ category_id: categoryId, url });
      if (saveErr) alert("Erro ao salvar categoria: " + saveErr.message);
      setCategoryImages((imgs) => ({ ...imgs, [categoryId]: url }));
    } catch (err) {
      setCatImgError("Não foi possível enviar a foto: " + err.message);
    } finally {
      setUploadingCatId(null);
    }
  };
  const removeCategoryImage = (categoryId) => {
    const url = categoryImages[categoryId];
    setCategoryImages((imgs) => { const n = { ...imgs }; delete n[categoryId]; return n; });
    supabase.from("app_category_images").delete().eq("category_id", categoryId);
    deleteFromSupabaseByUrl(url);
  };

  const [heroImgError, setHeroImgError] = useState("");
  const [uploadingHeroId, setUploadingHeroId] = useState(null);
  const handleHeroImage = (bannerId) => async (files) => {
    const file = files[0];
    if (!file) return;
    if (file.size > 8 * 1024 * 1024) {
      setHeroImgError("Imagem muito grande. Escolha um arquivo de até 8MB.");
      return;
    }
    setHeroImgError("");
    setUploadingHeroId(bannerId);
    try {
      const url = await uploadToSupabase(file, "banners");
      await supabase.from("app_hero_images").delete().eq("banner_id", bannerId);
      const { error: saveErr } = await supabase.from("app_hero_images").insert({ banner_id: bannerId, url });
      if (saveErr) alert("Erro ao salvar banner: " + saveErr.message);
      setHeroImages((imgs) => ({ ...imgs, [bannerId]: url }));
    } catch (err) {
      setHeroImgError("Não foi possível enviar a foto: " + err.message);
    } finally {
      setUploadingHeroId(null);
    }
  };
  const removeHeroImage = (bannerId) => {
    const url = heroImages[bannerId];
    setHeroImages((imgs) => { const n = { ...imgs }; delete n[bannerId]; return n; });
    supabase.from("app_hero_images").delete().eq("banner_id", bannerId);
    deleteFromSupabaseByUrl(url);
  };

  const [howToImgError, setHowToImgError] = useState("");
  const [uploadingHowToId, setUploadingHowToId] = useState(null);
  const handleHowToImage = (cardId) => async (files) => {
    const file = files[0];
    if (!file) return;
    if (file.size > 8 * 1024 * 1024) {
      setHowToImgError("Imagem muito grande. Escolha um arquivo de até 8MB.");
      return;
    }
    setHowToImgError("");
    setUploadingHowToId(cardId);
    try {
      const url = await uploadToSupabase(file, "como-comprar");
      await supabase.from("app_howto_images").delete().eq("card_id", cardId);
      const { error: saveErr } = await supabase.from("app_howto_images").insert({ card_id: cardId, url });
      if (saveErr) alert("Erro ao salvar card: " + saveErr.message);
      setHowToImages((imgs) => ({ ...imgs, [cardId]: url }));
    } catch (err) {
      setHowToImgError("Não foi possível enviar a foto: " + err.message);
    } finally {
      setUploadingHowToId(null);
    }
  };
  const removeHowToImage = (cardId) => {
    const url = howToImages[cardId];
    setHowToImages((imgs) => { const n = { ...imgs }; delete n[cardId]; return n; });
    supabase.from("app_howto_images").delete().eq("card_id", cardId);
    deleteFromSupabaseByUrl(url);
  };

  const updateOrderStatus = async (id, status) => {
    setOrders(orders.map((o) => o.id === id ? { ...o, status } : o));
    await supabase.from("app_orders").update({ status }).eq("id", id);
  };
  const archiveOrder = async (id) => {
    setOrders(orders.map((o) => o.id === id ? { ...o, archived: true } : o));
    await supabase.from("app_orders").update({ status: "arquivado" }).eq("id", id);
  };
  const ORDER_STATUSES = ["Novo", "Em separação", "Enviado", "Entregue", "Cancelado"];

  const emptyCouponForm = { code: "", discount: "", validade: "" };
  const [couponForm, setCouponForm] = useState(emptyCouponForm);
  const [editingCoupon, setEditingCoupon] = useState(null);
  const [couponFormError, setCouponFormError] = useState("");

  const startNewCoupon = () => { setEditingCoupon("new"); setCouponForm(emptyCouponForm); setCouponFormError(""); };
  const startEditCoupon = (c) => { setEditingCoupon(c.code); setCouponForm({ code: c.code, discount: c.discount, validade: c.validade || "" }); setCouponFormError(""); };
  const cancelCoupon = () => { setEditingCoupon(null); setCouponForm(emptyCouponForm); setCouponFormError(""); };

  const saveCoupon = () => {
    const code = couponForm.code.trim().toUpperCase();
    const discount = Number(couponForm.discount);
    if (!code || !discount || discount <= 0 || discount > 100) {
      setCouponFormError("Preencha um código e um desconto válido (1 a 100%).");
      return;
    }
    const duplicate = coupons.some((c) => c.code.toUpperCase() === code && c.code !== editingCoupon);
    if (duplicate) {
      setCouponFormError("Já existe um cupom com esse código.");
      return;
    }
    setCouponFormError("");
    if (editingCoupon === "new") {
      setCoupons([...coupons, { code, discount, validade: couponForm.validade, active: true }]);
    } else {
      setCoupons(coupons.map((c) => c.code === editingCoupon ? { ...c, code, discount, validade: couponForm.validade } : c));
    }
    cancelCoupon();
  };

  const removeCoupon = (code) => setCoupons(coupons.filter((c) => c.code !== code));
  const toggleCouponActive = (code) => setCoupons(coupons.map((c) => c.code === code ? { ...c, active: !c.active } : c));

  const isCouponExpired = (validade) => {
    if (!validade) return false;
    const d = new Date(validade + "T23:59:59");
    return !isNaN(d.getTime()) && d < new Date();
  };

  return (
    <div className="page-shell">
      <div className="admin-header-row">
        <h1 className="page-title" style={{ marginBottom: 0 }}>Painel administrativo</h1>
        <button className="btn btn-outline btn-sm" onClick={onLogout}><LogOut className="w-4 h-4" /> Sair</button>
      </div>
      <p className="txt-muted" style={{ marginBottom: "1.5rem" }}>Produtos, fotos, categorias, banners e cupons são salvos neste navegador quando você aperta "Salvar alterações" abaixo. Vídeos de produto continuam funcionando, mas por serem arquivos grandes, ficam só nesta sessão (somem se a página recarregar) até o site ter um servidor próprio.</p>

      <div className="admin-tabs">
        <button className={tab === "produtos" ? "admin-tab-active" : ""} onClick={() => setTab("produtos")}>Produtos</button>
        <button className={tab === "categorias" ? "admin-tab-active" : ""} onClick={() => setTab("categorias")}>Categorias</button>
        <button className={tab === "banners" ? "admin-tab-active" : ""} onClick={() => setTab("banners")}>Banners</button>
        <button className={tab === "pedidos" ? "admin-tab-active" : ""} onClick={() => setTab("pedidos")}>Pedidos</button>
        <button className={tab === "cupons" ? "admin-tab-active" : ""} onClick={() => setTab("cupons")}>Cupons</button>
        <button className={tab === "galeria" ? "admin-tab-active" : ""} onClick={() => setTab("galeria")}>Galeria</button>
      </div>

      {tab === "produtos" && (
        <div>
          <button className="btn btn-primary btn-sm" onClick={startNew} style={{ marginBottom: "1rem" }}><Plus className="w-4 h-4" /> Novo produto</button>
          {editing && (
            <div className="admin-form">
              <input placeholder="Nome do produto" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} />
              <select value={form.category} onChange={(e) => setForm({ ...form, category: e.target.value })}>
                {CATEGORIES.filter((c) => c.id !== "ofertas").map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
              </select>
              <input type="number" step="0.01" placeholder="Preço (ex: 49.90)" value={form.price} onChange={(e) => setForm({ ...form, price: e.target.value })} />
              <input type="number" placeholder="Estoque (0 = esgotado)" value={form.stock} onChange={(e) => setForm({ ...form, stock: e.target.value })} />

              <div className="admin-image-field">
                <label className="txt-muted" style={{ fontSize: "0.8rem", fontWeight: 600, display: "block", marginBottom: "0.4rem" }}>Fotos do produto (até 6)</label>
                <div className="admin-image-gallery">
                  {form.images.map((img, i) => (
                    <div key={i} className="admin-image-preview">
                      <img src={img} alt={`Foto ${i + 1}`} />
                      {i === 0 && <span className="admin-image-main-tag">Capa</span>}
                      <button type="button" className="admin-image-remove" onClick={() => removeImage(i)} aria-label="Remover foto"><X className="w-3.5 h-3.5" /></button>
                    </div>
                  ))}
                  {form.images.length < 6 && (
                    <FileField accept="image/*" multiple className="admin-upload-btn admin-upload-box" onFiles={handleProductImages}>
                      <Package className="w-5 h-5" />
                      <span>Adicionar foto</span>
                    </FileField>
                  )}
                </div>
                {imgError && <span className="coupon-err">{imgError}</span>}
              </div>

              <div className="admin-image-field">
                <label className="txt-muted" style={{ fontSize: "0.8rem", fontWeight: 600, display: "block", marginBottom: "0.4rem" }}>Vídeo do produto (opcional)</label>
                {form.video ? (
                  <div className="admin-video-preview">
                    <video src={form.video} controls />
                    <button type="button" className="admin-image-remove" onClick={() => setForm((f) => ({ ...f, video: null }))} aria-label="Remover vídeo"><X className="w-3.5 h-3.5" /></button>
                  </div>
                ) : (
                  <FileField accept="video/*" className="btn btn-outline btn-sm admin-upload-btn" onFiles={handleProductVideo}>
                    <Package className="w-4 h-4" /> Escolher vídeo
                  </FileField>
                )}
                {videoError && <span className="coupon-err">{videoError}</span>}
              </div>

              {formError && <span className="coupon-err" style={{ gridColumn: "1 / -1" }}>{formError}</span>}
              <div className="admin-form-actions">
                <button type="button" className="btn btn-primary btn-sm" onClick={save}>Salvar produto</button>
                <button type="button" className="btn btn-outline btn-sm" onClick={cancel}>Cancelar</button>
              </div>
            </div>
          )}
          {products.length === 0 && !editing && (
            <div className="empty-state" style={{ marginBottom: "1.25rem" }}>Nenhum produto cadastrado ainda. Clique em "Novo produto" para começar.</div>
          )}
          {products.length > 0 && (
            <div className="admin-table-wrap">
              <table className="admin-table">
                <thead><tr><th>Foto</th><th>Produto</th><th>Categoria</th><th>Preço</th><th>Estoque</th><th>Status</th><th>Ações</th></tr></thead>
                <tbody>
                  {products.map((p) => (
                    <tr key={p.id}>
                      <td>
                        {p.image ? <img src={p.image} alt={p.name} className="admin-thumb" /> : <div className="admin-thumb admin-thumb-empty"><Package className="w-4 h-4" /></div>}
                      </td>
                      <td>{p.name}</td>
                      <td>{CATEGORIES.find((c) => c.id === p.category)?.name}</td>
                      <td>{formatPrice(p.price)}</td>
                      <td>{p.stock}</td>
                      <td>
                        <span className={`status-pill ${p.stock <= 0 ? "status-pill-out" : ""}`}>{p.stock <= 0 ? "Esgotado" : "Em estoque"}</span>
                      </td>
                      <td className="admin-actions">
                        <button onClick={() => startEdit(p)}>Editar</button>
                        <button onClick={() => toggleEsgotado(p)}>{p.stock <= 0 ? "Repor estoque" : "Marcar esgotado"}</button>
                        <button onClick={() => remove(p.id)} className="danger">Excluir</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}

      {tab === "categorias" && (
        <div>
          <p className="txt-muted" style={{ marginBottom: "1rem" }}>Escolha uma foto de fundo para cada categoria. Elas aparecem nos quadrados da seção "Encontre o que você precisa".</p>
          {catImgError && <div className="coupon-err" style={{ marginBottom: "1rem" }}>{catImgError}</div>}
          <div className="admin-category-grid">
            {CATEGORIES.map((c) => {
              const isHidden = hiddenCategories.includes(c.id);
              return (
                <div key={c.id} className="admin-category-card" style={{ opacity: isHidden ? 0.5 : 1 }}>
                  <div className="admin-category-preview" style={categoryImages[c.id] ? { backgroundImage: `url(${categoryImages[c.id]})` } : undefined}>
                    {!categoryImages[c.id] && <c.icon className="w-6 h-6" />}
                  </div>
                  <span>{c.name}</span>
                  <div className="admin-category-actions">
                    <FileField accept="image/*" className="btn btn-outline btn-sm admin-upload-btn" onFiles={handleCategoryImage(c.id)}>
                      <Package className="w-4 h-4" /> {categoryImages[c.id] ? "Trocar" : "Adicionar foto"}
                    </FileField>
                    {categoryImages[c.id] && (
                      <button className="btn btn-outline btn-sm" onClick={() => removeCategoryImage(c.id)}>Remover</button>
                    )}
                    <button
                      className="btn btn-outline btn-sm"
                      style={{ color: isHidden ? "var(--brick)" : "var(--forest)" }}
                      onClick={() => setHiddenCategories((prev) => isHidden ? prev.filter((id) => id !== c.id) : [...prev, c.id])}
                    >
                      {isHidden ? "Mostrar" : "Ocultar"}
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {tab === "banners" && (
        <div>
          <p className="txt-muted" style={{ marginBottom: "1rem" }}>Escolha uma foto de fundo para cada um dos 3 banners que aparecem girando no topo da home.</p>
          {heroImgError && <div className="coupon-err" style={{ marginBottom: "1rem" }}>{heroImgError}</div>}
          <div className="admin-category-grid">
            {BANNERS.map((b) => (
              <div key={b.id} className="admin-category-card">
                <div className="admin-category-preview admin-banner-preview" style={heroImages[b.id] ? { backgroundImage: `url(${heroImages[b.id]})` } : undefined}>
                  {!heroImages[b.id] && <Package className="w-6 h-6" />}
                </div>
                <span>{b.title}</span>
                <div className="admin-category-actions">
                  <FileField accept="image/*" className="btn btn-outline btn-sm admin-upload-btn" onFiles={handleHeroImage(b.id)}>
                    <Package className="w-4 h-4" /> {heroImages[b.id] ? "Trocar" : "Adicionar foto"}
                  </FileField>
                  {heroImages[b.id] && (
                    <button className="btn btn-outline btn-sm" onClick={() => removeHeroImage(b.id)}>Remover</button>
                  )}
                </div>
              </div>
            ))}
          </div>

          <p className="txt-muted" style={{ margin: "2rem 0 1rem" }}>Escolha uma foto de fundo para cada card da seção "Como você quer comprar?".</p>
          {howToImgError && <div className="coupon-err" style={{ marginBottom: "1rem" }}>{howToImgError}</div>}
          <div className="admin-category-grid">
            {HOWTO_CARDS.map((c) => (
              <div key={c.id} className="admin-category-card">
                <div className="admin-category-preview admin-banner-preview" style={howToImages[c.id] ? { backgroundImage: `url(${howToImages[c.id]})` } : undefined}>
                  {!howToImages[c.id] && <c.icon className="w-6 h-6" />}
                </div>
                <span>{c.title}</span>
                <div className="admin-category-actions">
                  <FileField accept="image/*" className="btn btn-outline btn-sm admin-upload-btn" onFiles={handleHowToImage(c.id)}>
                    <Package className="w-4 h-4" /> {howToImages[c.id] ? "Trocar" : "Adicionar foto"}
                  </FileField>
                  {howToImages[c.id] && (
                    <button className="btn btn-outline btn-sm" onClick={() => removeHowToImage(c.id)}>Remover</button>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {tab === "pedidos" && (() => {
        const [showArchived, setShowArchived] = React.useState(false);
        const activeOrders = orders.filter((o) => showArchived ? o.status === "arquivado" : o.status !== "arquivado");

        const now = new Date();
        const startOfDay = new Date(now.getFullYear(), now.getMonth(), now.getDate());
        const startOfWeek = new Date(startOfDay); startOfWeek.setDate(startOfDay.getDate() - startOfDay.getDay());
        const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);

        const grupos = [
          { label: "Hoje", items: activeOrders.filter((o) => new Date(o.date) >= startOfDay) },
          { label: "Esta semana", items: activeOrders.filter((o) => new Date(o.date) >= startOfWeek && new Date(o.date) < startOfDay) },
          { label: "Este mês", items: activeOrders.filter((o) => new Date(o.date) >= startOfMonth && new Date(o.date) < startOfWeek) },
          { label: "Anteriores", items: activeOrders.filter((o) => new Date(o.date) < startOfMonth) },
        ].filter((g) => g.items.length > 0);

        const statusColor = { "Novo": "#D6A32C", "Em separação": "#3B82F6", "Enviado": "#8B5CF6", "Entregue": "#1F4B41", "Cancelado": "#DC2626" };

        return (
          <div>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "1rem" }}>
              <p className="txt-muted" style={{ margin: 0 }}>Pedidos finalizados pelo WhatsApp.</p>
              <button className="btn btn-outline btn-sm" onClick={() => setShowArchived((v) => !v)}>
                {showArchived ? "Ver ativos" : "Ver arquivados"}
              </button>
            </div>
            {activeOrders.length === 0 ? (
              <div className="empty-state">{showArchived ? "Nenhum pedido arquivado." : "Nenhum pedido ainda."}</div>
            ) : grupos.map((g) => (
              <div key={g.label} style={{ marginBottom: "1.5rem" }}>
                <h3 style={{ fontWeight: 700, fontSize: "1rem", marginBottom: "0.75rem", color: "#6b7280", textTransform: "uppercase", letterSpacing: "0.05em" }}>{g.label} · {g.items.length} pedido{g.items.length !== 1 ? "s" : ""}</h3>
                <div className="admin-orders-list">
                  {g.items.map((o) => (
                    <div key={o.id} className="admin-order-card">
                      <div className="admin-order-head">
                        <div>
                          <strong>{o.id}</strong> · {o.cliente}
                          <div className="txt-muted" style={{ fontSize: "0.76rem" }}>{new Date(o.date).toLocaleString("pt-BR")}</div>
                        </div>
                        <select
                          value={o.status}
                          onChange={(e) => updateOrderStatus(o.id, e.target.value)}
                          className="admin-order-status-select"
                          style={{ color: statusColor[o.status] || "#000", fontWeight: 600 }}
                        >
                          {ORDER_STATUSES.map((s) => <option key={s} value={s}>{s}</option>)}
                        </select>
                      </div>
                      <div className="admin-order-items">
                        {o.items.map((it, i) => (
                          <div key={i} className="summary-row"><span>{it.qty}x {it.name}</span><span>{formatPrice(it.price * it.qty)}</span></div>
                        ))}
                      </div>
                      {o.payment && <div className="txt-muted" style={{ fontSize: "0.8rem" }}>Pagamento: <strong>{o.payment}</strong></div>}
                      {o.coupon && <div className="txt-muted" style={{ fontSize: "0.8rem" }}>Cupom aplicado: <strong>{o.coupon}</strong></div>}
                      {o.obs && <div className="txt-muted" style={{ fontSize: "0.8rem" }}>Obs: {o.obs}</div>}
                      <div className="summary-row summary-total"><span>Total</span><span>{formatPrice(o.total)}</span></div>
                      {(o.status === "Entregue" || o.status === "Cancelado") && !showArchived && (
                        <button
                          className="btn btn-outline btn-sm"
                          style={{ marginTop: "0.5rem", width: "100%", color: "#6b7280" }}
                          onClick={() => archiveOrder(o.id)}
                        >
                          Arquivar pedido
                        </button>
                      )}
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        );
      })()}

      {tab === "cupons" && (
        <div>
          <p className="txt-muted" style={{ marginBottom: "1rem" }}>Crie códigos de desconto para passar para seus clientes. Eles funcionam de verdade no carrinho da loja.</p>
          <button className="btn btn-primary btn-sm" onClick={startNewCoupon} style={{ marginBottom: "1rem" }}><Plus className="w-4 h-4" /> Novo cupom</button>

          {editingCoupon && (
            <div className="admin-form">
              <input placeholder="Código (ex: TUPPER10)" value={couponForm.code} onChange={(e) => setCouponForm({ ...couponForm, code: e.target.value.toUpperCase() })} />
              <input type="number" min="1" max="100" placeholder="Desconto em % (ex: 10)" value={couponForm.discount} onChange={(e) => setCouponForm({ ...couponForm, discount: e.target.value })} />
              <input type="date" placeholder="Validade (opcional)" value={couponForm.validade} onChange={(e) => setCouponForm({ ...couponForm, validade: e.target.value })} />
              {couponFormError && <span className="coupon-err" style={{ gridColumn: "1 / -1" }}>{couponFormError}</span>}
              <div className="admin-form-actions">
                <button type="button" className="btn btn-primary btn-sm" onClick={saveCoupon}>Salvar cupom</button>
                <button type="button" className="btn btn-outline btn-sm" onClick={cancelCoupon}>Cancelar</button>
              </div>
            </div>
          )}

          {coupons.length === 0 && !editingCoupon && (
            <div className="empty-state">Nenhum cupom criado ainda. Clique em "Novo cupom" para começar.</div>
          )}

          {coupons.length > 0 && (
            <div className="admin-table-wrap">
              <table className="admin-table">
                <thead><tr><th>Código</th><th>Desconto</th><th>Validade</th><th>Status</th><th>Ações</th></tr></thead>
                <tbody>
                  {coupons.map((c) => {
                    const expired = isCouponExpired(c.validade);
                    return (
                      <tr key={c.code}>
                        <td><strong>{c.code}</strong></td>
                        <td>{c.discount}%</td>
                        <td>{c.validade ? new Date(c.validade + "T12:00:00").toLocaleDateString("pt-BR") : "Sem validade"}</td>
                        <td>
                          <span className={`status-pill ${(!c.active || expired) ? "status-pill-out" : ""}`}>
                            {expired ? "Expirado" : c.active ? "Ativo" : "Inativo"}
                          </span>
                        </td>
                        <td className="admin-actions">
                          <button onClick={() => startEditCoupon(c)}>Editar</button>
                          <button onClick={() => toggleCouponActive(c.code)}>{c.active ? "Desativar" : "Ativar"}</button>
                          <button onClick={() => removeCoupon(c.code)} className="danger">Excluir</button>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}

      {tab === "galeria" && (
        <GaleriaAdmin
          imagens={galeriaImagens}
          onUpload={(novas) => setGaleriaImagens((prev) => [...novas.map((n, i) => ({ id: Date.now() + i, ...n })), ...prev])}
          onDelete={async (img) => {
            await deleteFromSupabaseByUrl(img.url);
            setGaleriaImagens((prev) => prev.filter((i) => i.id !== img.id));
          }}
        />
      )}

      <div className="admin-save-bar">
        <span className="txt-muted admin-save-hint">
          {isSaving ? "Salvando fotos, produtos e cupons..." : "Lembre-se de salvar antes de sair."}
        </span>
        <button type="button" className="btn btn-primary admin-save-btn" onClick={onSaveAll} disabled={isSaving}>
          {isSaving ? (
            <>
              <span className="spinner" /> Salvando...
            </>
          ) : (
            <>
              <Check className="w-4 h-4" /> Salvar alterações
            </>
          )}
        </button>
      </div>
      <div className="admin-save-bar-spacer" />
    </div>
  );
}

/* ============================= APP ============================= */

/* ============================= GALERIA PÚBLICA ============================= */

function GaleriaPublica({ imagens }) {
  if (!imagens.length) return null;
  return (
    <section style={{ padding: "2rem 1rem", maxWidth: "1200px", margin: "0 auto" }}>
      <h2 style={{ marginBottom: "1.25rem", fontSize: "1.5rem", fontWeight: 700 }}>Galeria</h2>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(180px, 1fr))", gap: "1rem" }}>
        {imagens.map((img) => (
          <div key={img.id} style={{ borderRadius: "0.5rem", overflow: "hidden", aspectRatio: "1", background: "#f3f4f6" }}>
            <img src={img.url} alt={img.name} style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }} loading="lazy" />
          </div>
        ))}
      </div>
    </section>
  );
}

/* ============================= GALERIA ADMIN ============================= */

function GaleriaAdmin({ imagens, onDelete, onUpload }) {
  const [uploading, setUploading] = useState(false);

  const handleFiles = async (files) => {
    setUploading(true);
    try {
      const novas = await Promise.all(
        Array.from(files).map(async (f) => {
          const url = await uploadToSupabase(f, "galeria");
          return { name: f.name, url };
        })
      );
      onUpload(novas);
    } catch (err) {
      console.error("Erro no upload:", err);
    } finally {
      setUploading(false);
    }
  };

  return (
    <div style={{ marginTop: "1.5rem" }}>
      <h3 style={{ fontWeight: 700, marginBottom: "0.75rem" }}>Galeria de imagens</h3>
      <FileField onFiles={handleFiles} accept="image/*" multiple>
        <button type="button" className="btn btn-primary" disabled={uploading} style={{ marginBottom: "1rem" }}>
          {uploading ? "Enviando…" : "Adicionar imagens"}
        </button>
      </FileField>
      {imagens.length === 0 && <p className="txt-muted">Nenhuma imagem na galeria ainda.</p>}
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(140px, 1fr))", gap: "0.75rem", marginTop: "0.75rem" }}>
        {imagens.map((img) => (
          <div key={img.id} style={{ position: "relative", borderRadius: "0.5rem", overflow: "hidden", aspectRatio: "1", background: "#f3f4f6" }}>
            <img src={img.url} alt={img.name} style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }} loading="lazy" />
            <button
              type="button"
              onClick={() => onDelete(img)}
              style={{ position: "absolute", top: 4, right: 4, background: "rgba(0,0,0,0.6)", border: "none", borderRadius: "50%", width: 28, height: 28, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center" }}
              aria-label="Deletar imagem"
            >
              <X style={{ width: 14, height: 14, color: "#fff" }} />
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

export default function App() {
  const [products, setProducts] = useState(RAW_PRODUCTS);
  const [page, setPage] = useState("home");
  const [selectedProductId, setSelectedProductId] = useState(null);
  const [categoryFilter, setCategoryFilter] = useState("todas");
  const [searchQuery, setSearchQuery] = useState("");
  const [cart, setCart] = useState([]);
  const [searchOpen, setSearchOpen] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  const [isAdminAuth, setIsAdminAuth] = useState(false);

  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setIsAdminAuth(!!session);
    });
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setIsAdminAuth(!!session);
    });
    return () => subscription.unsubscribe();
  }, []);
  const [categoryImages, setCategoryImages] = useState({});
  const [hiddenCategories, setHiddenCategories] = useState([]);
  const [heroImages, setHeroImages] = useState({});
  const [howToImages, setHowToImages] = useState({});
  const [coupons, setCoupons] = useState([
    { code: "TUPPER10", discount: 10, validade: "", active: true },
  ]);
  const [orders, setOrders] = useState([]);
  const addOrder = async (order) => {
    setOrders((o) => [order, ...o]);
    await supabase.from("app_orders").insert({
      id: order.id, cliente: order.cliente, date: order.date,
      items: order.items, payment: order.payment || null,
      coupon: order.coupon || null, obs: order.obs || null,
      total: order.total, status: order.status || "Novo",
    });
  };

  const [galeriaImagens, setGaleriaImagens] = useState([]);

  useEffect(() => {
    supabase.from("imagens").select("*").order("id", { ascending: false })
      .then(({ data }) => { if (data) setGaleriaImagens(data); });
  }, []);

  const [isSaving, setIsSaving] = useState(false);
  const [toast, setToast] = useState(null);
  const [hasLoadedStorage, setHasLoadedStorage] = useState(false);

  useEffect(() => {
    let cancelled = false;
    loadAllFromSupabase()
      .then((saved) => {
        if (cancelled) return;
        if (saved.products) setProducts(saved.products);
        if (Object.keys(saved.categoryImages).length) setCategoryImages(saved.categoryImages);
        if (Object.keys(saved.heroImages).length) setHeroImages(saved.heroImages);
        if (Object.keys(saved.howToImages).length) setHowToImages(saved.howToImages);
        if (saved.coupons) setCoupons(saved.coupons);
        if (saved.hiddenCategories && saved.hiddenCategories.length) setHiddenCategories(saved.hiddenCategories);
        if (saved.orders && saved.orders.length) setOrders(saved.orders);
      })
      .catch(() => { /* sem dados salvos ainda, segue com o padrão */ })
      .finally(() => { if (!cancelled) setHasLoadedStorage(true); });
    return () => { cancelled = true; };
  }, []);

  const saveAllChanges = async () => {
    setIsSaving(true);
    try {
      await saveAllToSupabase({ products, categoryImages, heroImages, howToImages, coupons, hiddenCategories });
      setToast({ type: "success", message: "Alterações salvas com sucesso!" });
    } catch (err) {
      alert("Erro ao salvar: " + (err.message || JSON.stringify(err)));
      setToast({ type: "error", message: "Não foi possível salvar. Tente novamente." });
    } finally {
      setIsSaving(false);
    }
  };

  const goTo = (p, opts = {}) => {
    setPage(p);
    if (opts.productId) setSelectedProductId(opts.productId);
    setSearchOpen(false);
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  const viewProduct = (id) => goTo("produto", { productId: id });

  const addToCart = (product, qty = 1, color = Object.keys(SWATCHES)[0]) => {
    setCart((c) => {
      const idx = c.findIndex((i) => i.productId === product.id && i.color === color);
      if (idx >= 0) {
        const copy = [...c];
        copy[idx] = { ...copy[idx], qty: copy[idx].qty + qty };
        return copy;
      }
      return [...c, { productId: product.id, qty, color }];
    });
  };
  const updateQty = (productId, color, qty) => setCart((c) => c.map((i) => (i.productId === productId && i.color === color ? { ...i, qty } : i)));
  const removeItem = (productId, color) => setCart((c) => c.filter((i) => !(i.productId === productId && i.color === color)));
  const clearCart = () => setCart([]);

  const cartCount = cart.reduce((s, i) => s + i.qty, 0);
  const bestSellers = products.filter((p) => p.badge === "mais-vendido");
  const offers = products.filter((p) => p.oldPrice);
  const news = products.filter((p) => p.badge === "novo");
  const selectedProduct = products.find((p) => p.id === selectedProductId);

  const submitSearch = () => {
    goTo("busca");
  };

  const waContextMsg = page === "produto" && selectedProduct
    ? `Olá! Tenho interesse no produto ${selectedProduct.name}. Gostaria de saber mais informações.`
    : "Olá! Vim pelo site e gostaria de saber mais sobre os produtos.";

  return (
    <div className="app-root">
      <GlobalStyles />
      <Header goTo={goTo} cartCount={cartCount} searchOpen={searchOpen} setSearchOpen={setSearchOpen}
        query={searchQuery} setQuery={setSearchQuery} menuOpen={menuOpen} setMenuOpen={setMenuOpen} onSubmitSearch={submitSearch} />

      <main>
        {page === "home" && (
          <>
            <HeroBanner goTo={goTo} heroImages={heroImages} />
            <Reveal><HowToBuy goTo={goTo} howToImages={howToImages} /></Reveal>
            <CategorySection key={Object.keys(categoryImages).join(",")} goTo={goTo} setCategoryFilter={setCategoryFilter} categoryImages={categoryImages} hiddenCategories={hiddenCategories} />
            {products.length > 0 && (
              <>
                {bestSellers.length > 0 && <Reveal><ProductRow title="Mais vendidos" products={bestSellers} goTo={goTo} addToCart={addToCart} viewProduct={viewProduct} carousel /></Reveal>}
                {offers.length > 0 && <Reveal><OffersSection products={offers} goTo={goTo} addToCart={addToCart} viewProduct={viewProduct} /></Reveal>}
                {news.length > 0 && <Reveal><ProductRow title="Novidades que acabaram de chegar" products={news} goTo={goTo} addToCart={addToCart} viewProduct={viewProduct} carousel /></Reveal>}
              </>
            )}
            <Reveal><AboutSection /></Reveal>
            <Reveal><Newsletter /></Reveal>
            <Reveal><GaleriaPublica imagens={galeriaImagens} /></Reveal>
          </>
        )}

        {page === "busca" && (
          <BuscaPage products={products} initialQuery={searchQuery} initialCategory={categoryFilter} goTo={goTo} addToCart={addToCart} viewProduct={viewProduct} />
        )}

        {page === "categorias" && (
          <div className="page-shell">
            <h1 className="page-title">Categorias</h1>
            <CategorySection goTo={goTo} setCategoryFilter={setCategoryFilter} categoryImages={categoryImages} hiddenCategories={hiddenCategories} />
          </div>
        )}

        {page === "ofertas" && (
          <div className="page-shell">
            <h1 className="page-title">Ofertas por tempo limitado</h1>
            {offers.length > 0 ? (
              <OffersSection products={offers} goTo={goTo} addToCart={addToCart} viewProduct={viewProduct} />
            ) : (
              <div className="empty-state">Nenhuma oferta no momento. Volte em breve!</div>
            )}
          </div>
        )}

        {page === "produto" && (
          <ProductPage product={selectedProduct} allProducts={products} goTo={goTo} addToCart={addToCart} viewProduct={viewProduct} />
        )}

        {page === "carrinho" && (
          <CartPage cart={cart} products={products} updateQty={updateQty} removeItem={removeItem} goTo={goTo} clearCart={clearCart} coupons={coupons} addOrder={addOrder} />
        )}

        {page === "sobre" && <SobrePage />}
        {page === "contato" && <ContatoPage />}
        {page === "conta" && <ContaPage goTo={goTo} />}
        {page === "admin" && (
          isAdminAuth
            ? <AdminPage products={products} setProducts={setProducts} categoryImages={categoryImages} setCategoryImages={setCategoryImages} heroImages={heroImages} setHeroImages={setHeroImages} howToImages={howToImages} setHowToImages={setHowToImages} coupons={coupons} setCoupons={setCoupons} orders={orders} setOrders={setOrders} onSaveAll={saveAllChanges} isSaving={isSaving} galeriaImagens={galeriaImagens} setGaleriaImagens={setGaleriaImagens} hiddenCategories={hiddenCategories} setHiddenCategories={setHiddenCategories} onLogout={async () => { await supabase.auth.signOut(); setIsAdminAuth(false); goTo("home"); }} />
            : <AdminLogin onSuccess={() => setIsAdminAuth(true)} goTo={goTo} />
        )}
      </main>

      <Footer goTo={goTo} />
      <WhatsAppButton contextMessage={waContextMsg} />
      <Toast toast={toast} onClose={() => setToast(null)} />
    </div>
  );
}

/* ============================= ESTILOS GLOBAIS ============================= */

function GlobalStyles() {
  return (
    <style>{`
      @import url('https://fonts.googleapis.com/css2?family=Fraunces:ital,opsz,wght@0,9..144,400;0,9..144,500;0,9..144,600;0,9..144,700;1,9..144,500&family=Sora:wght@400;500;600;700&display=swap');

      :root {
        --ink: #1B3226;
        --forest: #1F4B41;
        --forest-dark: #163329;
        --sage-bg: #F3F5EE;
        --cream: #FBFAF6;
        --gold: #D6A32C;
        --gold-dark: #B8871C;
        --brick: #C1443C;
        --line: #E3E1D6;
      }
      * { box-sizing: border-box; }

      /* ===== Animações ===== */
      .reveal { opacity: 0; transform: translateY(26px); transition: opacity 0.7s cubic-bezier(0.16,1,0.3,1), transform 0.7s cubic-bezier(0.16,1,0.3,1); }
      .reveal-visible { opacity: 1; transform: translateY(0); }

      .reveal-visible .howto-card,
      .reveal-visible .category-card,
      .reveal-visible .product-card,
      .reveal-visible .product-card-compact,
      .reveal-visible .mini-info-card,
      .reveal-visible .contact-card {
        opacity: 0; transform: translateY(18px);
        animation: itemRise 0.6s cubic-bezier(0.16,1,0.3,1) forwards;
      }
      .reveal-visible .howto-card:nth-child(1), .reveal-visible .category-card:nth-child(1), .reveal-visible .product-card:nth-child(1) { animation-delay: 0.05s; }
      .reveal-visible .howto-card:nth-child(2), .reveal-visible .category-card:nth-child(2), .reveal-visible .product-card:nth-child(2) { animation-delay: 0.12s; }
      .reveal-visible .howto-card:nth-child(3), .reveal-visible .category-card:nth-child(3), .reveal-visible .product-card:nth-child(3) { animation-delay: 0.19s; }
      .reveal-visible .category-card:nth-child(4), .reveal-visible .product-card:nth-child(4) { animation-delay: 0.26s; }
      .reveal-visible .category-card:nth-child(5), .reveal-visible .product-card:nth-child(5) { animation-delay: 0.33s; }
      .reveal-visible .category-card:nth-child(6), .reveal-visible .product-card:nth-child(6) { animation-delay: 0.4s; }
      .reveal-visible .category-card:nth-child(7) { animation-delay: 0.47s; }
      .reveal-visible .category-card:nth-child(8), .reveal-visible .category-card:nth-child(9) { animation-delay: 0.54s; }
      .reveal-visible .product-card-compact:nth-child(1) { animation-delay: 0.04s; }
      .reveal-visible .product-card-compact:nth-child(2) { animation-delay: 0.1s; }
      .reveal-visible .product-card-compact:nth-child(3) { animation-delay: 0.16s; }
      .reveal-visible .product-card-compact:nth-child(4) { animation-delay: 0.22s; }
      @keyframes itemRise { to { opacity: 1; transform: translateY(0); } }

      .page-shell, .success-panel, .admin-login-card { animation: pageFadeIn 0.5s cubic-bezier(0.16,1,0.3,1); }
      @keyframes pageFadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }

      .hero-content { animation: heroRise 0.75s cubic-bezier(0.16,1,0.3,1); }
      .hero-visual { animation: heroPop 0.8s cubic-bezier(0.16,1,0.3,1); }
      @keyframes heroRise { from { opacity: 0; transform: translateY(22px); } to { opacity: 1; transform: translateY(0); } }
      @keyframes heroPop { from { opacity: 0; transform: scale(0.85); } to { opacity: 1; transform: scale(1); } }

      .mobile-menu-overlay { animation: overlayFadeIn 0.25s ease; }
      .mobile-menu { animation: menuSlideIn 0.32s cubic-bezier(0.16,1,0.3,1); }
      @keyframes overlayFadeIn { from { opacity: 0; } to { opacity: 1; } }
      @keyframes menuSlideIn { from { transform: translateX(-100%); } to { transform: translateX(0); } }

      .search-pop { animation: popIn 0.18s ease; transform-origin: top right; }
      @keyframes popIn { from { opacity: 0; transform: scale(0.92) translateY(-6px); } to { opacity: 1; transform: scale(1) translateY(0); } }

      .wa-float { animation: waPulse 2.6s ease-in-out infinite; }
      .wa-float:hover { animation-play-state: paused; }
      @keyframes waPulse { 0%, 100% { box-shadow: 0 10px 24px rgba(37,211,102,0.4), 0 0 0 0 rgba(46,218,80,0.45); } 50% { box-shadow: 0 10px 24px rgba(37,211,102,0.4), 0 0 0 10px rgba(46,218,80,0); } }

      .cart-badge { animation: badgePop 0.35s cubic-bezier(0.34,1.56,0.64,1); }
      @keyframes badgePop { from { transform: scale(0); } to { transform: scale(1); } }

      .logo-mark { transition: transform 0.2s ease; }
      .logo:hover .logo-mark { transform: rotate(-6deg) scale(1.05); }

      /* Respeita quem prefere menos movimento na tela (acessibilidade) */
      @media (prefers-reduced-motion: reduce) {
        .reveal, .reveal-visible, .reveal-visible .howto-card, .reveal-visible .category-card,
        .reveal-visible .product-card, .reveal-visible .product-card-compact, .reveal-visible .mini-info-card,
        .reveal-visible .contact-card, .page-shell, .success-panel, .admin-login-card, .hero-content,
        .hero-visual, .mobile-menu-overlay, .mobile-menu, .search-pop, .wa-float, .cart-badge {
          animation: none !important;
          transition: none !important;
          opacity: 1 !important;
          transform: none !important;
        }
      }

      html, body { overflow-x: hidden; max-width: 100%; }
      .app-root { font-family: 'Sora', sans-serif; color: var(--ink); background: var(--cream); min-height: 100vh; overflow-x: hidden; width: 100%; }
      .app-root h1, .app-root h2, .app-root h3, .app-root h4, .logo-word { font-family: 'Fraunces', serif; }
      .app-root button { cursor: pointer; font-family: inherit; }
      .app-root input, .app-root select { font-family: inherit; }
      .txt-muted { color: #7A7A6E; }
      .only-mobile { display: none; }
      @media (max-width: 860px) { .only-desktop { display: none !important; } .only-mobile { display: inline-flex; } }

      /* Header */
      .site-header { position: sticky; top: 0; z-index: 50; background: var(--cream); border-bottom: 1px solid var(--line); }
      .header-inner { max-width: 1240px; margin: 0 auto; display: flex; align-items: center; gap: 1.25rem; padding: 0.85rem 1.5rem; }
      .logo { display: flex; align-items: center; gap: 0.5rem; background: none; border: none; margin-right: 0.5rem; }
      .logo-mark { width: 38px; height: 38px; border-radius: 10px; background: linear-gradient(135deg, #2A6B58 0%, #1F4B41 45%, #B8871C 100%); color: var(--cream); display: flex; align-items: center; justify-content: center; font-family: 'Fraunces', serif; font-weight: 600; font-size: 0.95rem; letter-spacing: -0.02em; flex-shrink: 0; box-shadow: 0 3px 8px rgba(31,75,65,0.35), inset 0 1px 0 rgba(255,255,255,0.25); }
      .logo-word { font-weight: 600; font-size: clamp(1rem, 2.4vw, 1.3rem); letter-spacing: 0.01em; color: var(--forest); white-space: nowrap; }
      .main-nav { display: flex; gap: 1.6rem; flex: 1; }
      .nav-link { background: none; border: none; color: var(--ink); font-size: 0.92rem; font-weight: 500; padding: 0.4rem 0; border-bottom: 2px solid transparent; }
      .nav-link:hover { border-bottom: 2px solid var(--gold); }
      .header-actions { display: flex; align-items: center; gap: 0.4rem; margin-left: auto; }
      .icon-btn { background: none; border: none; width: 38px; height: 38px; border-radius: 50%; display: flex; align-items: center; justify-content: center; color: var(--ink); }
      .icon-btn:hover { background: var(--sage-bg); }
      .cart-btn { position: relative; }
      .cart-badge { position: absolute; top: 0; right: 0; background: var(--brick); color: white; font-size: 0.65rem; min-width: 17px; height: 17px; border-radius: 999px; display: flex; align-items: center; justify-content: center; font-weight: 700; }
      .search-wrap { position: relative; }
      .search-pop { position: absolute; right: 0; top: 46px; background: white; border: 1px solid var(--line); border-radius: 12px; box-shadow: 0 12px 30px rgba(0,0,0,0.1); padding: 0.4rem; display: flex; align-items: center; gap: 0.3rem; }
      .search-pop input { width: 240px; border: none; outline: none; padding: 0.5rem; font-size: 0.9rem; }
      .search-pop-btn { background: var(--forest); color: white; border: none; width: 34px; height: 34px; border-radius: 8px; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }

      .mobile-menu-overlay { position: fixed; inset: 0; background: rgba(20,25,20,0.4); z-index: 60; }
      .mobile-menu { background: var(--cream); width: 82%; max-width: 320px; height: 100%; padding: 1.25rem; display: flex; flex-direction: column; gap: 0.25rem; }
      .mobile-menu-top { display: flex; justify-content: space-between; align-items: center; margin-bottom: 1rem; }
      .mobile-menu-link { text-align: left; background: none; border: none; padding: 0.8rem 0.2rem; border-bottom: 1px solid var(--line); font-size: 1rem; }

      /* Buttons */
      .btn { display: inline-flex; align-items: center; justify-content: center; gap: 0.5rem; border-radius: 999px; padding: 0.75rem 1.5rem; font-weight: 600; font-size: 0.92rem; border: none; text-decoration: none; transition: transform 0.15s ease, box-shadow 0.15s ease; }
      .btn:active { transform: scale(0.98); }
      .btn-primary { background: var(--forest); color: var(--cream); }
      .btn-primary:hover { background: var(--forest-dark); }
      .btn-outline { background: transparent; color: var(--forest); border: 1.5px solid var(--forest); }
      .btn-outline:hover { background: var(--sage-bg); }
      .btn-ghost-light { background: rgba(255,255,255,0.15); color: white; border: 1.5px solid rgba(255,255,255,0.7); }
      .btn-ghost-light:hover { background: rgba(255,255,255,0.28); }
      .btn-whatsapp { background: #1F4B41; color: white; display: inline-flex; align-items: center; gap: 0.5rem; margin-top: 0.75rem; border-radius: 999px; padding: 0.75rem 1.5rem; font-weight: 600; }
      .btn-sm { padding: 0.55rem 1.1rem; font-size: 0.82rem; }
      .link-more { background: none; border: none; color: var(--forest); font-weight: 600; display: inline-flex; align-items: center; gap: 0.25rem; font-size: 0.88rem; }

      /* Hero */
      .hero { position: relative; display: grid; grid-template-columns: 1.1fr 0.9fr; align-items: center; padding: 3.5rem 1.5rem; min-height: 480px; overflow: hidden; color: white; }
      .hero-photo { background-size: cover; background-position: center; }
      .hero-scrim { position: absolute; inset: 0; background: linear-gradient(100deg, rgba(10,20,15,0.78) 0%, rgba(10,20,15,0.45) 55%, rgba(10,20,15,0.15) 100%); z-index: 1; }
      .hero-photo .hero-content { position: relative; z-index: 2; }
      .hero-photo .hero-dots { z-index: 3; }
      .hero-forest { background: linear-gradient(120deg, #1F4B41, #163329); }
      .hero-gold { background: linear-gradient(120deg, #B8871C, #8F6A15); }
      .hero-brick { background: linear-gradient(120deg, #C1443C, #8E322C); }
      .hero-content { max-width: 560px; margin: 0 auto; padding-left: 2rem; z-index: 2; }
      .eyebrow { text-transform: uppercase; letter-spacing: 0.14em; font-size: 0.72rem; font-weight: 700; color: var(--gold); }
      .eyebrow-dark { color: var(--gold-dark); }
      .hero-title { font-size: 2.6rem; line-height: 1.1; margin: 0.6rem 0 0.9rem; font-weight: 600; }
      .hero-subtitle { font-size: 1.02rem; opacity: 0.92; margin-bottom: 1.5rem; }
      .hero-actions { display: flex; gap: 0.9rem; flex-wrap: wrap; }
      .hero-visual { position: relative; display: flex; align-items: center; justify-content: center; height: 100%; }
      .hero-blob { position: absolute; width: 320px; height: 320px; border-radius: 50%; background: rgba(255,255,255,0.12); }
      .hero-icon { width: 160px; height: 160px; color: rgba(255,255,255,0.85); position: relative; z-index: 2; }
      .hero-dots { position: absolute; bottom: 1.25rem; left: 50%; transform: translateX(-50%); display: flex; gap: 0.4rem; z-index: 3; }
      .hero-dot { width: 8px; height: 8px; border-radius: 50%; background: rgba(255,255,255,0.4); border: none; padding: 0; }
      .hero-dot.active { background: white; width: 22px; border-radius: 999px; }
      @media (max-width: 860px) { .hero { grid-template-columns: 1fr; padding: 2.5rem 1.25rem 3.5rem; text-align: center; } .hero-content { padding-left: 0; margin: 0 auto 1.5rem; } .hero-actions { justify-content: center; } .hero-title { font-size: 1.9rem; } .hero-visual { height: 200px; } .hero-icon { width: 110px; height: 110px; } }

      /* Sections */
      .section { max-width: 1240px; margin: 0 auto; padding: 3rem 1.5rem; }
      .section-alt { background: var(--sage-bg); max-width: none; }
      .section-alt > * { max-width: 1240px; margin-left: auto; margin-right: auto; }
      .section-title { font-size: 1.7rem; font-weight: 600; margin-bottom: 1.5rem; text-align: center; }
      .section-head { display: flex; justify-content: space-between; align-items: flex-end; margin-bottom: 1.25rem; gap: 1rem; flex-wrap: wrap; }
      .section-head .section-title { text-align: left; margin-bottom: 0; }

      /* How to buy */
      .howto-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.5rem; }
      .howto-card { position: relative; overflow: hidden; border-radius: 22px; padding: 2.5rem 1.75rem; text-align: center; display: flex; flex-direction: column; align-items: center; gap: 0.7rem; min-height: 340px; justify-content: center; color: white; box-shadow: 0 14px 30px rgba(20,30,20,0.14); }
      .howto-forest { background: linear-gradient(155deg, #1F4B41, #123028); }
      .howto-gold { background: linear-gradient(155deg, #D6A32C, #A67318); }
      .howto-brick { background: linear-gradient(155deg, #C1443C, #862F29); }
      .howto-rays { position: absolute; inset: -20%; background: repeating-conic-gradient(rgba(255,255,255,0.05) 0deg 8deg, transparent 8deg 16deg); opacity: 0.5; pointer-events: none; }
      .howto-card-photo { background-size: cover; background-position: center; }
      .howto-scrim { position: absolute; inset: 0; background: linear-gradient(180deg, rgba(10,20,15,0.35) 0%, rgba(10,20,15,0.65) 100%); }
      .howto-icon { position: relative; z-index: 1; width: 68px; height: 68px; border-radius: 18px; display: flex; align-items: center; justify-content: center; margin-bottom: 0.3rem; background: rgba(255,255,255,0.18); border: 1.5px solid rgba(255,255,255,0.5); }
      .howto-card h3 { position: relative; z-index: 1; font-size: 1.3rem; font-weight: 600; margin: 0; }
      .howto-card p { position: relative; z-index: 1; color: rgba(255,255,255,0.88); font-size: 0.92rem; margin: 0 0 0.4rem; max-width: 280px; }
      .btn-howto { position: relative; z-index: 1; background: white; color: var(--ink); border-radius: 999px; padding: 0.75rem 1.6rem; font-weight: 700; }
      .btn-howto:hover { background: rgba(255,255,255,0.9); }
      .t-forest { background: rgba(31,75,65,0.12); color: var(--forest); }
      .t-gold { background: rgba(214,163,44,0.16); color: var(--gold-dark); }
      .t-brick { background: rgba(193,68,60,0.12); color: var(--brick); }
      @media (max-width: 860px) { .howto-grid { grid-template-columns: 1fr; } }

      /* Categories */
      .category-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1rem; }
      .category-card { position: relative; background: white; border: 1px solid var(--line); border-radius: 16px; padding: 1.5rem 1rem; display: flex; flex-direction: column; align-items: center; justify-content: flex-end; gap: 0.6rem; font-weight: 600; font-size: 0.9rem; min-height: 140px; overflow: hidden; }
      .category-card:hover { border-color: var(--forest); transform: translateY(-2px); transition: 0.15s; }
      .category-icon { width: 52px; height: 52px; border-radius: 50%; display: flex; align-items: center; justify-content: center; }
      .category-card-photo { background-size: cover; background-position: center; border: none; color: white; padding-bottom: 1.1rem; }
      .category-card-photo span { position: relative; z-index: 2; text-shadow: 0 2px 6px rgba(0,0,0,0.4); }
      .category-card-scrim { position: absolute; inset: 0; background: linear-gradient(to top, rgba(10,22,16,0.75) 0%, rgba(10,22,16,0.15) 60%, rgba(10,22,16,0) 100%); z-index: 1; }
      @media (max-width: 860px) { .category-grid { grid-template-columns: repeat(2, 1fr); } }

      /* Product cards */
      .product-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.5rem; }
      .product-scroll { display: flex; gap: 1.25rem; overflow-x: auto; padding-bottom: 0.75rem; scroll-snap-type: x mandatory; }
      .product-scroll .product-card-compact { min-width: 280px; scroll-snap-align: start; }
      @media (max-width: 1024px) { .product-grid { grid-template-columns: repeat(2, 1fr); } }
      @media (max-width: 720px) { .product-grid { grid-template-columns: repeat(2, 1fr); gap: 0.9rem; } .product-card { min-height: 260px; } }

      .product-card { position: relative; border-radius: 20px; overflow: hidden; aspect-ratio: 3/4; min-height: 340px; cursor: pointer; box-shadow: 0 10px 26px rgba(30,50,40,0.10); transition: transform 0.18s ease, box-shadow 0.18s ease; background: linear-gradient(160deg, #EDF1E7, #F8F6EF); }
      .product-card:hover { transform: translateY(-5px); box-shadow: 0 22px 38px rgba(30,50,40,0.18); }
      .product-card-compact { min-width: 260px; }
      .product-card > .prod-visual { position: absolute; inset: 0; border-radius: 0; }
      .prod-visual { position: relative; aspect-ratio: 1.15/1; display: flex; align-items: center; justify-content: center; background: linear-gradient(160deg, #EDF1E7, #F8F6EF); }
      .prod-visual-photo { background-size: cover; background-position: center; }
      .prod-visual-ring { position: absolute; width: 62%; height: 62%; border-radius: 50%; background: radial-gradient(circle, rgba(31,75,65,0.10), transparent 70%); }
      .prod-visual-icon { width: 34%; height: 34%; color: var(--forest); position: relative; z-index: 2; }
      .prod-visual-big { aspect-ratio: 1/1; border-radius: 20px; min-height: 340px; }
      .prod-visual-gradient { position: absolute; inset: 0; background: linear-gradient(to top, rgba(10,20,15,0.55) 0%, rgba(10,20,15,0) 55%); z-index: 2; }
      .prod-visual-scrim { position: absolute; left: 0; right: 0; bottom: 0; height: 62%; background: linear-gradient(to top, rgba(10,22,16,0.92) 0%, rgba(10,22,16,0.55) 55%, rgba(10,22,16,0) 100%); z-index: 3; }
      .badge-pill { position: absolute; top: 12px; left: 12px; font-size: 0.7rem; font-weight: 700; padding: 0.32rem 0.7rem; border-radius: 999px; z-index: 5; }
      .product-card-overlay { position: absolute; left: 0; right: 0; bottom: 0; z-index: 4; padding: 1.1rem 1.2rem 1.2rem; display: flex; flex-direction: column; gap: 0.4rem; }
      .prod-title-overlay { color: white; font-size: 1.02rem; font-weight: 600; line-height: 1.3; margin: 0; text-shadow: 0 2px 8px rgba(0,0,0,0.3); }
      .price-row { display: flex; align-items: baseline; gap: 0.5rem; flex-wrap: wrap; }
      .price-old { text-decoration: line-through; color: #A6A296; font-size: 0.82rem; }
      .price-old-overlay { color: rgba(255,255,255,0.7); }
      .price-now { font-size: 1.1rem; font-weight: 700; color: var(--forest); }
      .price-now-overlay { color: white; font-size: 1.35rem; }
      .price-now-lg { font-size: 1.9rem; }
      .price-discount { background: rgba(193,68,60,0.12); color: var(--brick); font-size: 0.72rem; font-weight: 700; padding: 0.15rem 0.45rem; border-radius: 6px; }
      .price-discount-overlay { position: absolute; top: 12px; right: 12px; background: var(--brick); color: white; z-index: 5; }
      .btn-card-cta { width: 100%; margin-top: 0.3rem; padding: 0.7rem; font-size: 0.85rem; }
      .btn-disabled { background: rgba(255,255,255,0.25); color: white; cursor: not-allowed; }
      .badge-mais-vendido { background: var(--forest); color: white; }
      .badge-oferta { background: var(--brick); color: white; }
      .badge-novo { background: var(--gold); color: var(--ink); }
      /* Offers */
      .offers-section { background: linear-gradient(180deg, #FBF6E8, transparent); border-radius: 24px; }
      .countdown { display: flex; align-items: center; gap: 0.4rem; color: var(--brick); font-size: 0.88rem; }

      /* About */
      .about-section { display: grid; grid-template-columns: 0.9fr 1.1fr; gap: 2.5rem; align-items: center; }
      .about-section-text { grid-template-columns: 1fr; max-width: 720px; text-align: left; }
      .about-visual { position: relative; background: var(--forest); border-radius: 24px; aspect-ratio: 1/0.9; display: flex; align-items: center; justify-content: center; overflow: hidden; }
      .about-blob { position: absolute; width: 70%; height: 70%; border-radius: 50%; background: rgba(255,255,255,0.08); }
      .about-icon { width: 40%; height: 40%; color: rgba(255,255,255,0.85); position: relative; z-index: 2; }
      .about-copy p { color: #55554A; line-height: 1.6; margin: 0.75rem 0 1.2rem; }
      .about-list { list-style: none; padding: 0; display: flex; flex-direction: column; gap: 0.6rem; }
      .about-list li { display: flex; align-items: center; gap: 0.6rem; font-weight: 500; }
      .about-list svg { color: var(--forest); flex-shrink: 0; }
      @media (max-width: 860px) { .about-section { grid-template-columns: 1fr; } }

      /* Newsletter */
      .newsletter { background: var(--forest); color: white; text-align: center; padding: 3.5rem 1.5rem; }
      .newsletter h2 { font-size: 1.6rem; margin-bottom: 0.5rem; }
      .newsletter p { max-width: 480px; margin: 0 auto 1.5rem; opacity: 0.85; }
      .newsletter-form { display: flex; gap: 0.6rem; justify-content: center; flex-wrap: wrap; max-width: 460px; margin: 0 auto; }
      .newsletter-form input { flex: 1; min-width: 220px; padding: 0.8rem 1.1rem; border-radius: 999px; border: none; outline: none; }
      .newsletter-success { display: inline-flex; align-items: center; gap: 0.5rem; background: rgba(255,255,255,0.15); padding: 0.7rem 1.2rem; border-radius: 999px; }

      /* Footer */
      .site-footer { background: var(--forest-dark); color: rgba(255,255,255,0.85); padding: 3rem 1.5rem 1.5rem; }
      .footer-grid { max-width: 1240px; margin: 0 auto; display: grid; grid-template-columns: 1.4fr repeat(3, 1fr); gap: 2rem; }
      .footer-brand p { font-size: 0.88rem; opacity: 0.75; margin: 0.6rem 0 1rem; max-width: 260px; }
      .footer-social { display: flex; gap: 0.6rem; }
      .footer-social a { width: 34px; height: 34px; border-radius: 50%; background: rgba(255,255,255,0.1); display: flex; align-items: center; justify-content: center; color: white; }
      .footer-col h4 { color: white; font-size: 0.85rem; text-transform: uppercase; letter-spacing: 0.08em; margin-bottom: 0.9rem; font-family: 'Sora', sans-serif; font-weight: 700; }
      .footer-col button, .footer-col a { display: block; background: none; border: none; color: rgba(255,255,255,0.75); font-size: 0.88rem; text-align: left; padding: 0.35rem 0; text-decoration: none; }
      .footer-col button:hover, .footer-col a:hover { color: white; }
      .footer-bottom { max-width: 1240px; margin: 2.5rem auto 0; padding-top: 1.5rem; border-top: 1px solid rgba(255,255,255,0.12); display: flex; justify-content: space-between; align-items: center; font-size: 0.78rem; opacity: 0.7; flex-wrap: wrap; gap: 0.5rem; }
      .footer-admin-link { background: none; border: none; color: rgba(255,255,255,0.35); display: flex; align-items: center; justify-content: center; padding: 0.3rem; border-radius: 50%; }
      .footer-admin-link:hover { color: rgba(255,255,255,0.7); }
      @media (max-width: 860px) { .footer-grid { grid-template-columns: repeat(2, 1fr); } }

      /* WhatsApp float */
      .wa-float { position: fixed; bottom: 22px; right: 22px; width: 60px; height: 60px; border-radius: 50%; display: flex; align-items: center; justify-content: center; box-shadow: 0 10px 24px rgba(37,211,102,0.4); z-index: 70; background: #2EDA50; overflow: hidden; }
      .wa-float-icon { width: 118%; height: 118%; object-fit: cover; }
      .wa-float:hover { transform: scale(1.06); }

      /* Generic page shell */
      .page-shell { max-width: 1240px; margin: 0 auto; padding: 2.5rem 1.5rem 4rem; min-height: 50vh; }
      .page-title { font-size: 1.9rem; font-weight: 600; margin-bottom: 1.5rem; }
      .empty-state { background: white; border: 1px dashed var(--line); border-radius: 18px; padding: 3rem 1.5rem; text-align: center; color: #6C6C60; }

      /* Busca */
      .busca-layout { display: grid; grid-template-columns: 240px 1fr; gap: 2rem; align-items: flex-start; }
      .filters-panel { background: white; border: 1px solid var(--line); border-radius: 16px; padding: 1.25rem; display: flex; flex-direction: column; gap: 1rem; position: sticky; top: 90px; }
      .filters-head { display: none; justify-content: space-between; align-items: center; }
      .filter-block { display: flex; flex-direction: column; gap: 0.4rem; }
      .filter-block label { font-size: 0.8rem; font-weight: 600; }
      .filter-block input, .filter-block select, .filter-block textarea { padding: 0.6rem 0.7rem; border-radius: 10px; border: 1px solid var(--line); outline: none; font-size: 0.88rem; font-family: inherit; resize: vertical; }
      .busca-toolbar { display: flex; justify-content: space-between; align-items: center; margin-bottom: 1rem; }
      @media (max-width: 860px) {
        .busca-layout { grid-template-columns: 1fr; }
        .filters-panel { display: none; }
        .filters-panel.filters-open { display: flex; position: fixed; inset: 0; z-index: 65; border-radius: 0; overflow-y: auto; }
        .filters-head { display: flex; }
      }

      /* Product detail */
      .product-detail { display: grid; grid-template-columns: 1fr 1fr; gap: 2.5rem; }
      .product-gallery { display: flex; flex-direction: column; gap: 0.9rem; }
      .gallery-thumbs { display: flex; gap: 0.5rem; }
      .thumb { width: 30px; height: 30px; border-radius: 50%; border: 2px solid var(--line); }
      .thumb-active { border-color: var(--forest); box-shadow: 0 0 0 2px rgba(31,75,65,0.2); }
      .product-info h1 { font-size: 1.6rem; font-weight: 600; margin: 0.6rem 0 0.5rem; }
      .product-desc { color: #55554A; line-height: 1.6; margin: 0.9rem 0; }
      .qty-row { display: flex; align-items: center; gap: 1rem; margin: 1rem 0; }
      .qty-row label { font-weight: 600; font-size: 0.85rem; }
      .stepper { display: flex; align-items: center; gap: 0.75rem; border: 1px solid var(--line); border-radius: 999px; padding: 0.3rem 0.7rem; }
      .stepper button { background: none; border: none; width: 24px; height: 24px; display: flex; align-items: center; justify-content: center; color: var(--forest); }
      .product-cta-row { display: flex; gap: 0.75rem; margin: 1rem 0 0.25rem; flex-wrap: wrap; }
      .product-cta-row .btn { flex: 1; min-width: 180px; }
      .spec-table { margin: 1.5rem 0; border-top: 1px solid var(--line); }
      .spec-table > div { display: flex; justify-content: space-between; padding: 0.6rem 0; border-bottom: 1px solid var(--line); font-size: 0.88rem; }
      .spec-table span:first-child { color: #7A7A6E; }
      .feature-list { list-style: none; padding: 0; display: flex; flex-direction: column; gap: 0.5rem; margin: 0 0 1.25rem; }
      .feature-list li { display: flex; gap: 0.5rem; font-size: 0.88rem; align-items: flex-start; }
      .feature-list svg { color: var(--forest); flex-shrink: 0; margin-top: 0.15rem; }
      .trust-row { display: flex; gap: 1.5rem; flex-wrap: wrap; color: #6C6C60; font-size: 0.82rem; }
      .trust-row span { display: flex; align-items: center; gap: 0.4rem; }
      @media (max-width: 860px) { .product-detail { grid-template-columns: 1fr; } }

      /* Cart */
      .cart-layout { display: grid; grid-template-columns: 1fr 340px; gap: 2rem; align-items: flex-start; }
      .cart-items { display: flex; flex-direction: column; gap: 0.9rem; }
      .cart-item { display: grid; grid-template-columns: 64px 1fr auto auto auto; align-items: center; gap: 1rem; background: white; border: 1px solid var(--line); border-radius: 14px; padding: 0.75rem; }
      .cart-item-visual { width: 64px; height: 64px; border-radius: 10px; }
      .cart-item-visual .prod-visual-icon { width: 40%; height: 40%; }
      .cart-item-visual .badge-pill, .cart-item-visual .prod-visual-scrim, .cart-item-visual .prod-visual-gradient { display: none; }
      .cart-item-info { display: flex; flex-direction: column; gap: 0.15rem; }
      .cart-item-name { font-weight: 600; font-size: 0.88rem; }
      .cart-item-total { font-weight: 700; color: var(--forest); }
      .cart-summary { background: white; border: 1px solid var(--line); border-radius: 16px; padding: 1.5rem; position: sticky; top: 90px; }
      .cart-summary h3 { margin-top: 0; }
      .coupon-row { display: flex; gap: 0.5rem; margin-bottom: 0.5rem; }
      .coupon-row input { flex: 1; padding: 0.6rem 0.8rem; border-radius: 10px; border: 1px solid var(--line); outline: none; }
      .coupon-ok { color: var(--forest); font-size: 0.82rem; margin-bottom: 0.5rem; }
      .coupon-err { color: var(--brick); font-size: 0.82rem; margin-bottom: 0.5rem; }
      .payment-radio-group { display: flex; gap: 0.6rem; flex-wrap: wrap; }
      .payment-radio-option { display: flex; align-items: center; gap: 0.5rem; border: 1.5px solid var(--line); border-radius: 999px; padding: 0.55rem 1rem 0.55rem 0.7rem; font-size: 0.88rem; font-weight: 600; cursor: pointer; transition: border-color 0.15s ease, background 0.15s ease; }
      .payment-radio-option input { position: absolute; opacity: 0; width: 0; height: 0; }
      .payment-radio-dot { width: 18px; height: 18px; border-radius: 50%; border: 2px solid #B9B6A8; flex-shrink: 0; display: flex; align-items: center; justify-content: center; transition: border-color 0.15s ease; }
      .payment-radio-dot::after { content: ""; width: 10px; height: 10px; border-radius: 50%; background: var(--forest); transform: scale(0); transition: transform 0.15s cubic-bezier(0.34,1.56,0.64,1); }
      .payment-radio-active { border-color: var(--forest); background: var(--sage-bg); }
      .payment-radio-active .payment-radio-dot { border-color: var(--forest); }
      .payment-radio-active .payment-radio-dot::after { transform: scale(1); }
      .summary-row { display: flex; justify-content: space-between; font-size: 0.9rem; padding: 0.5rem 0; border-bottom: 1px solid var(--line); }
      .summary-discount { color: var(--brick); }
      .summary-total { font-weight: 700; font-size: 1.05rem; border-bottom: none; color: var(--forest); }
      @media (max-width: 860px) { .cart-layout { grid-template-columns: 1fr; } .cart-item { grid-template-columns: 50px 1fr; grid-template-areas: 'v i' 'v s' 'v t'; } }

      /* Mini info / contact */
      .mini-info-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.25rem; }
      .mini-info-card { background: white; border: 1px solid var(--line); border-radius: 16px; padding: 1.5rem; text-align: center; }
      .mini-info-card svg { color: var(--forest); margin-bottom: 0.5rem; }
      .contact-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1.25rem; }
      .contact-card { background: white; border: 1px solid var(--line); border-radius: 16px; padding: 1.5rem; text-align: center; display: flex; flex-direction: column; align-items: center; gap: 0.4rem; }
      .contact-card svg { color: var(--forest); }
      @media (max-width: 860px) { .mini-info-grid, .contact-grid { grid-template-columns: 1fr 1fr; } }

      /* Admin */
      /* Admin login */
      .admin-login-shell { display: flex; align-items: center; justify-content: center; min-height: 60vh; }
      .admin-login-card { background: white; border: 1px solid var(--line); border-radius: 20px; padding: 2.5rem; max-width: 380px; width: 100%; text-align: center; box-shadow: 0 16px 40px rgba(20,30,20,0.08); }
      .admin-login-icon { width: 54px; height: 54px; border-radius: 50%; background: var(--sage-bg); color: var(--forest); display: flex; align-items: center; justify-content: center; margin: 0 auto 1rem; }
      .admin-login-form { display: flex; flex-direction: column; gap: 0.6rem; }
      .admin-login-form input { padding: 0.75rem 1rem; border-radius: 10px; border: 1px solid var(--line); outline: none; text-align: center; font-size: 0.95rem; }
      .admin-header-row { display: flex; justify-content: space-between; align-items: center; gap: 1rem; margin-bottom: 0.5rem; flex-wrap: wrap; }
      .admin-save-bar { position: fixed; left: 0; right: 0; bottom: 0; z-index: 60; background: white; border-top: 1px solid var(--line); box-shadow: 0 -8px 24px rgba(20,30,20,0.08); padding: 0.85rem 1.5rem; display: flex; align-items: center; justify-content: flex-end; gap: 1rem; }
      .admin-save-hint { font-size: 0.8rem; }
      .admin-save-btn { min-width: 190px; justify-content: center; }
      .admin-save-btn:disabled { opacity: 0.75; cursor: not-allowed; }
      .admin-save-bar-spacer { height: 76px; }
      .spinner { width: 15px; height: 15px; border-radius: 50%; border: 2px solid rgba(255,255,255,0.4); border-top-color: white; animation: spin 0.7s linear infinite; display: inline-block; }
      @keyframes spin { to { transform: rotate(360deg); } }
      .toast { position: fixed; top: 20px; left: 50%; transform: translateX(-50%); z-index: 100; display: flex; align-items: center; gap: 0.5rem; padding: 0.8rem 1.3rem; border-radius: 999px; color: white; font-weight: 600; font-size: 0.88rem; box-shadow: 0 12px 28px rgba(0,0,0,0.2); animation: toastIn 0.3s cubic-bezier(0.34,1.56,0.64,1); }
      .toast-success { background: var(--forest); }
      .toast-error { background: var(--brick); }
      @keyframes toastIn { from { opacity: 0; transform: translateX(-50%) translateY(-14px); } to { opacity: 1; transform: translateX(-50%) translateY(0); } }
      @media (max-width: 860px) { .admin-save-bar { padding: 0.75rem 1rem; } .admin-save-hint { display: none; } }

      .admin-tabs { display: flex; gap: 0.5rem; margin-bottom: 1.5rem; border-bottom: 1px solid var(--line); overflow-x: auto; -webkit-overflow-scrolling: touch; scrollbar-width: thin; }
      .admin-tabs button { background: none; border: none; padding: 0.7rem 1.1rem; font-weight: 600; color: #7A7A6E; border-bottom: 2px solid transparent; white-space: nowrap; flex-shrink: 0; }
      .admin-tab-active { color: var(--forest) !important; border-bottom: 2px solid var(--forest) !important; }
      .admin-form { display: grid; grid-template-columns: 1fr 1fr; gap: 0.75rem; background: white; border: 1px solid var(--line); border-radius: 14px; padding: 1.25rem; margin-bottom: 1.25rem; }
      .admin-form input, .admin-form select { padding: 0.6rem 0.8rem; border-radius: 10px; border: 1px solid var(--line); outline: none; }
      .admin-form-actions { grid-column: 1 / -1; display: flex; gap: 0.5rem; }
      .admin-table-wrap { background: white; border: 1px solid var(--line); border-radius: 14px; overflow-x: auto; }
      .admin-table { width: 100%; border-collapse: collapse; font-size: 0.88rem; }
      .admin-table th { text-align: left; padding: 0.9rem 1rem; background: var(--sage-bg); font-size: 0.78rem; text-transform: uppercase; letter-spacing: 0.04em; color: #6C6C60; }
      .admin-table td { padding: 0.9rem 1rem; border-top: 1px solid var(--line); }
      .admin-actions { display: flex; gap: 0.75rem; }
      .admin-actions button { background: none; border: none; color: var(--forest); font-weight: 600; font-size: 0.82rem; }
      .admin-actions .danger { color: var(--brick); }
      .status-pill { background: var(--sage-bg); color: var(--forest); padding: 0.25rem 0.6rem; border-radius: 999px; font-size: 0.76rem; font-weight: 600; }
      .status-pill-out { background: rgba(193,68,60,0.14); color: var(--brick); }
      .admin-image-field { grid-column: 1 / -1; display: flex; flex-direction: column; gap: 0.5rem; }
      .admin-image-gallery { display: flex; flex-wrap: wrap; gap: 0.75rem; align-items: flex-start; }
      .admin-upload-btn { display: inline-flex; align-items: center; gap: 0.5rem; cursor: pointer; }
      .file-field { position: relative; overflow: hidden; }
      .file-field input[type="file"] { position: absolute; inset: 0; width: 100%; height: 100%; opacity: 0; cursor: pointer; margin: 0; padding: 0; font-size: 100px; }
      .admin-upload-box { flex-direction: column; justify-content: center; width: 80px; height: 80px; border: 1.5px dashed var(--line); border-radius: 10px; color: var(--forest); font-size: 0.68rem; text-align: center; gap: 0.3rem; background: var(--sage-bg); }
      .admin-image-preview { position: relative; width: 80px; height: 80px; border-radius: 10px; overflow: hidden; border: 1px solid var(--line); }
      .admin-image-preview img { width: 100%; height: 100%; object-fit: cover; }
      .admin-image-main-tag { position: absolute; bottom: 0; left: 0; right: 0; background: rgba(31,75,65,0.85); color: white; font-size: 0.6rem; text-align: center; padding: 0.15rem 0; font-weight: 600; }
      .admin-image-remove { position: absolute; top: 2px; right: 2px; background: rgba(20,25,20,0.65); color: white; border: none; width: 18px; height: 18px; border-radius: 50%; display: flex; align-items: center; justify-content: center; }
      .admin-video-preview { position: relative; width: 100%; max-width: 340px; }
      .admin-video-preview video { width: 100%; border-radius: 10px; border: 1px solid var(--line); background: black; }
      .admin-video-preview .admin-image-remove { top: 6px; right: 6px; }
      .admin-thumb { width: 44px; height: 44px; border-radius: 8px; object-fit: cover; }
      .admin-thumb-empty { background: var(--sage-bg); color: var(--forest); display: flex; align-items: center; justify-content: center; }
      .admin-category-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); gap: 1.25rem; }
      .admin-category-card { background: white; border: 1px solid var(--line); border-radius: 14px; padding: 1rem; display: flex; flex-direction: column; align-items: center; gap: 0.6rem; text-align: center; }
      .admin-category-card span { font-weight: 600; font-size: 0.88rem; }
      .admin-category-preview { width: 100%; aspect-ratio: 1.3/1; border-radius: 10px; background: var(--sage-bg); color: var(--forest); display: flex; align-items: center; justify-content: center; background-size: cover; background-position: center; }
      .admin-banner-preview { aspect-ratio: 16/9; }
      .admin-category-actions { display: flex; flex-direction: column; gap: 0.4rem; width: 100%; }
      .admin-orders-list { display: flex; flex-direction: column; gap: 1rem; }
      .admin-order-card { background: white; border: 1px solid var(--line); border-radius: 14px; padding: 1.1rem 1.25rem; }
      .admin-order-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 1rem; margin-bottom: 0.6rem; flex-wrap: wrap; }
      .admin-order-status-select { padding: 0.4rem 0.7rem; border-radius: 999px; border: 1px solid var(--line); font-size: 0.78rem; font-weight: 600; color: var(--forest); background: var(--sage-bg); }
      .admin-order-items { border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); padding: 0.3rem 0; margin-bottom: 0.4rem; }
    `}</style>
  );
}
